/* Darsi — contenido en ESPAÑOL (traducido del francés, lengua de referencia).
   Las referencias 'q:', 'h:', 'f:' no se traducen. Contenido pendiente de revisión por una persona competente. */
'use strict';
CONTENU.es={
lecons:{
/* ===================== RAMADÁN Y AYUNO ===================== */
'r-bienvenue':{titre:"El mes de Ramadán",
 texte:["Ramadán es el 9.º mes del calendario musulmán, llamado calendario de la Hégira. Este calendario es lunar: cada mes comienza con la aparición de la nueva luna creciente.",
  "El año lunar tiene unos 354 días. Por eso Ramadán se adelanta unos diez días cada año en nuestro calendario.",
  "Fue durante este mes cuando comenzó la revelación del Corán. El ayuno de Ramadán se hizo obligatorio en el 2.º año de la Hégira."],
 retenir:"Ramadán es el 9.º mes lunar, el mes del Corán y del ayuno.",
 sources:['q:2:185','h:croissant'],
 quiz:[
  {q:"En el calendario musulmán (de la Hégira), ¿qué lugar ocupa el mes de Ramadán?",c:["El 9.º mes","El 1.er mes","El 12.º mes","El 7.º mes"],b:0,e:"Ramadán es el 9.º mes. El 1.er mes del año de la Hégira es Muharram.",s:['f:mois']},
  {q:"¿En qué astro se basa el calendario musulmán (de la Hégira)?",c:["La luna","El sol","Las estrellas","En ningún astro"],b:0,e:"Cada mes comienza con la aparición de la nueva luna creciente.",s:['q:2:189','h:croissant']},
  {q:"¿Por qué la fecha de Ramadán se adelanta unos 11 días cada año?",c:["Porque el año lunar es más corto que el año solar","Porque los sabios la desplazan cada año","Porque el año de la Hégira tiene 13 meses","Porque se sigue el calendario solar persa"],b:0,e:"El año lunar tiene unos 354 días, es decir, unos 11 días menos que el año solar.",s:['q:9:36']},
  {q:"¿Qué acontecimiento importante comenzó durante el mes de Ramadán?",c:["La revelación del Corán","La construcción de la Kaaba","La Hégira a Medina","La batalla de Uhud"],b:0,e:"El Corán comenzó a ser revelado durante Ramadán.",s:['q:2:185']},
  {q:"¿Cuántos meses tiene el año musulmán (de la Hégira)?",c:["12","10","13","11"],b:0,e:"El año de la Hégira tiene 12 meses lunares.",s:['q:9:36']},
  {q:"Según el hadiz, ¿con qué señal se comienza el ayuno de Ramadán?",c:["Cuando se ve la nueva luna creciente","Cuando se ve la luna llena","El 15 de Shaabán, cada año","Después del primer viernes tras Shaabán"],b:0,e:"«Ayunad cuando la veáis»: se trata de la luna creciente.",s:['h:croissant']},
  {q:"¿Cómo se llama el mes que sigue a Ramadán, cuyo 1.er día es el Eid al-Fitr?",c:["Shawwal","Shaabán","Rajab","Muharram"],b:0,e:"El 1 de Shawwal es el día del Eid al-Fitr.",s:['f:mois']},
  {q:"¿Qué mes del calendario musulmán precede directamente a Ramadán?",c:["Shaabán","Shawwal","Dhul-Hiyya","Safar"],b:0,e:"Shaabán es el 8.º mes, justo antes de Ramadán.",s:['f:mois']},
  {q:"¿En qué año de la Hégira se hizo obligatorio el ayuno de Ramadán?",c:["El año 2","El año 1","El año 10","El año 8"],b:0,e:"El ayuno de Ramadán fue prescrito en Medina, en el año 2 de la Hégira.",s:['f:jeune2']},
  {q:"¿Cuántos días puede durar el mes de Ramadán?",c:["29 o 30 días","Siempre 30 días","28 días","31 días"],b:0,e:"Un mes lunar dura 29 o 30 días, según la aparición de la siguiente luna creciente.",s:['h:croissant']}
 ]},
'r-jeuner':{titre:"¿Quién debe ayunar?",
 texte:["El ayuno de Ramadán es obligatorio para el musulmán púber, en su sano juicio y capaz de ayunar.",
  "El enfermo y el viajero pueden no ayunar y recuperar los días más tarde. La mujer con la menstruación no ayuna y recupera después.",
  "La persona que nunca podrá ayunar, como una persona muy mayor, alimenta a un pobre por cada día no ayunado: es la fidya."],
 retenir:"Existen facilidades: Allah quiere para nosotros la facilidad.",
 sources:['q:2:184','q:2:185'],
 quiz:[
  {q:"Durante Ramadán, ¿qué debe hacer el viajero que no ha ayunado algunos días?",c:["Recuperar esos días más tarde","Nada en absoluto","Pagar una multa","Ayunar el doble"],b:0,e:"Recupera el mismo número de días después de Ramadán.",s:['q:2:184']},
  {q:"¿Cómo se llama la compensación que consiste en alimentar a un pobre por cada día de ayuno no realizado?",c:["La fidya","La sadaqa","El zakat al-fitr","La kaffara"],b:0,e:"La fidya concierne sobre todo a quienes nunca podrán recuperar, como las personas muy mayores.",s:['q:2:184']},
  {q:"¿Es obligatorio el ayuno de Ramadán para un niño que no ha llegado a la pubertad?",c:["No, pero se le puede ir acostumbrando","Sí, desde los 7 años","Sí, pero solo los viernes","Solo durante los diez últimos días"],b:0,e:"No es obligatorio. Sin embargo, los compañeros acostumbraban a sus hijos al ayuno, por ejemplo el día de Ashura.",s:['h:enfants']},
  {q:"Durante Ramadán, ¿qué hace la mujer que tiene la menstruación?",c:["No ayuna y recupera los días después","Ayuna de todos modos","Nunca recupera","Ayuna la mitad del día"],b:0,e:"No ayuna y luego recupera los días perdidos después de Ramadán.",s:['h:regles']},
  {q:"¿Debe el enfermo que no ayuna durante Ramadán recuperar los días perdidos?",c:["Sí, cuando pueda","No, nunca","Sí, pero el doble","No, siempre paga una multa"],b:0,e:"Recupera el mismo número de días cuando es capaz.",s:['q:2:184']},
  {q:"¿Debe la mujer con la menstruación recuperar las oraciones que no ha hecho durante ese periodo?",c:["No, solo recupera el ayuno","Sí, todas las oraciones","Sí, la mitad de las oraciones","Solo la oración del viernes"],b:0,e:"Recupera el ayuno, pero no la oración.",s:['h:regles']},
  {q:"Según la aleya sobre el ayuno, ¿qué quiere Allah para los creyentes?",c:["La facilidad","La dificultad","El cansancio","La riqueza"],b:0,e:"«Allah quiere para vosotros la facilidad y no quiere para vosotros la dificultad.»",s:['q:2:185']},
  {q:"Una persona muy mayor que ya nunca podrá ayunar: ¿qué hace?",c:["Alimenta a un pobre por cada día","Ayuna de todos modos","No tiene que hacer nada","Recupera después del siguiente Ramadán"],b:0,e:"Es la fidya: una comida para un pobre por cada día no ayunado.",s:['q:2:184']},
  {q:"¿Para quién es obligatorio el ayuno de Ramadán?",c:["El musulmán púber, en su sano juicio y capaz de ayunar","Todos los niños","Solo los hombres","Solo quienes han hecho el hajj"],b:0,e:"Son las condiciones que establecen los sabios.",s:['f:conditions']},
  {q:"Según el Corán, ¿se prescribió el ayuno antes de los musulmanes?",c:["Sí, a quienes los precedieron","No, nunca","Solo a la gente de La Meca","Solo al pueblo de Nuh"],b:0,e:"«Se os ha prescrito el ayuno como se prescribió a quienes os precedieron.»",s:['q:2:183']}
 ]},
'r-rompt':{titre:"Lo que rompe el ayuno",
 texte:["El ayuno comienza al alba, en el momento de la oración del Fajr, y termina a la puesta del sol, en el momento de la oración del Maghrib.",
  "Comer, beber o tener relaciones íntimas voluntariamente durante el día rompe el ayuno.",
  "Quien come o bebe por olvido continúa su ayuno: sigue siendo válido."],
 retenir:"Comer o beber por olvido no anula el ayuno.",
 sources:['q:2:187','h:oubli'],
 quiz:[
  {q:"¿En qué momento del día comienza el ayuno de Ramadán?",c:["Al alba (Fajr)","A medianoche","A la salida del sol","A mediodía"],b:0,e:"El ayuno comienza al alba, cuando el hilo blanco se distingue del hilo negro.",s:['q:2:187']},
  {q:"¿En qué momento se rompe el ayuno de Ramadán?",c:["A la puesta del sol (Maghrib)","Cuando ya es noche cerrada (Isha)","A las 16 h","A mitad de la noche"],b:0,e:"Se rompe el ayuno en cuanto el sol se ha puesto.",s:['h:coucher']},
  {q:"Una persona que ayuna bebe agua habiendo olvidado que ayunaba. ¿Qué pasa con su ayuno?",c:["Sigue siendo válido","Queda anulado","Debe hacerlo doble","Depende de la cantidad"],b:0,e:"Completa su ayuno: es Allah quien le ha dado de comer y de beber.",s:['h:oubli']},
  {q:"¿Qué ocurre si una persona que ayuna come voluntariamente en pleno día de Ramadán?",c:["Su ayuno queda roto","No cambia nada","Está permitido si está en la mezquita","Está permitido después de la oración del Dhuhr"],b:0,e:"Comer voluntariamente durante el día rompe el ayuno.",s:['q:2:187']},
  {q:"Según el Corán, ¿hasta cuándo se puede comer y beber durante las noches de Ramadán?",c:["Hasta que el hilo blanco del alba se distinga del hilo negro de la noche","Hasta medianoche","Hasta la salida del sol","Hasta la oración del Isha"],b:0,e:"Es la imagen de la aleya 187 de la sura Al-Baqara.",s:['q:2:187']},
  {q:"En la aleya sobre el ayuno, ¿qué representa «el hilo blanco»?",c:["La luz del alba","Un hilo de lana de verdad","La luna creciente","La primera estrella de la tarde"],b:0,e:"El hilo blanco es la claridad del alba; el hilo negro, la oscuridad de la noche.",s:['q:2:187']},
  {q:"Durante Ramadán, ¿está permitido comer y beber de noche, después de la puesta del sol?",c:["Sí, hasta el alba","No, nunca durante todo el mes","Solo agua","Solo después de la oración de tarawih"],b:0,e:"El ayuno solo concierne al día, desde el alba hasta la puesta del sol.",s:['q:2:187']},
  {q:"Según el hadiz, ¿quién ha «dado de comer y de beber» a quien come o bebe por olvido durante el ayuno?",c:["Allah","Su familia","Un ángel","Nadie"],b:0,e:"Su ayuno sigue siendo válido: es Allah quien le ha dado de comer y de beber.",s:['h:oubli']},
  {q:"Durante los días de Ramadán, ¿están permitidas las relaciones íntimas entre esposos?",c:["No, rompen el ayuno","Sí, en cualquier momento","Sí, por la tarde","Solo el día de Ashura"],b:0,e:"La aleya 187 las permite durante las noches de Ramadán; durante el día, rompen el ayuno.",s:['q:2:187']},
  {q:"¿Qué oración marca el final de la jornada de ayuno?",c:["La oración del Maghrib","La oración del Fajr","La oración del Dhuhr","La oración del Isha"],b:0,e:"El Maghrib es la oración de la puesta del sol, la hora de romper el ayuno.",s:['h:coucher']}
 ]},
'r-suhur':{titre:"El suhur y el iftar",
 texte:["El suhur es la comida que se toma antes del alba. El Profeta ﷺ animó a tomarla, porque contiene una bendición.",
  "El iftar es la ruptura del ayuno a la puesta del sol. Se recomienda no retrasarlo.",
  "La sunna es romper el ayuno con dátiles frescos; si no, con dátiles secos; si no, con unos sorbos de agua."],
 retenir:"Suhur antes del alba. Iftar en cuanto se pone el sol, con dátiles.",
 sources:['h:suhur','h:dattes'],
 quiz:[
  {q:"¿Cómo se llama la comida que se toma antes del alba durante Ramadán?",c:["El suhur","El iftar","La walima","La aqiqa"],b:0,e:"El suhur es la comida del final de la noche, antes del Fajr.",s:['h:suhur']},
  {q:"Según el hadiz, ¿qué contiene la comida del suhur?",c:["Una bendición","Una obligación","Nada en particular","Una prueba"],b:0,e:"«Tomad el suhur, porque en el suhur hay una bendición.»",s:['h:suhur']},
  {q:"¿Con qué rompía el Profeta ﷺ su ayuno preferentemente?",c:["Con dátiles","Con leche de camella","Con harira","Con pan"],b:0,e:"Dátiles frescos; si no, dátiles secos; si no, unos sorbos de agua.",s:['h:dattes']},
  {q:"¿Hay que retrasar la ruptura del ayuno (el iftar) después de la puesta del sol?",c:["No, se recomienda apresurarse","Sí, una hora","Sí, hasta el Isha","No tiene ninguna importancia"],b:0,e:"Se recomienda romper el ayuno en cuanto se pone el sol.",s:['h:hater']},
  {q:"¿Cómo se llama la comida que rompe el ayuno a la puesta del sol?",c:["El iftar","El suhur","El ghusl","El dhikr"],b:0,e:"El iftar es la ruptura del ayuno.",s:['h:hater']},
  {q:"Cuando no había dátiles, ¿con qué rompía el Profeta ﷺ su ayuno?",c:["Con unos sorbos de agua","Con miel","Con leche de cabra","Con higos"],b:0,e:"Dátiles frescos; si no, secos; si no, unos sorbos de agua.",s:['h:dattes']},
  {q:"¿Rompía el Profeta ﷺ su ayuno antes o después de la oración del Maghrib?",c:["Antes de rezar","Después de haber rezado","Al día siguiente","Después de la oración del Isha"],b:0,e:"Rompía su ayuno antes de rezar, con algunos dátiles.",s:['h:dattes']},
  {q:"Según el hadiz, mientras la gente se apresure a romper el ayuno, seguirá…",c:["En el bien","En la duda","En peligro","Sin recompensa"],b:0,e:"«La gente no dejará de estar en el bien mientras se apresure a romper el ayuno.»",s:['h:hater']},
  {q:"¿Es obligatorio el suhur para que el ayuno sea válido?",c:["No, pero es muy recomendado","Sí, si no el ayuno queda anulado","Sí, solo el primer día","Está prohibido"],b:0,e:"Es una sunna: el Profeta ﷺ lo animó por su bendición.",s:['h:suhur']},
  {q:"¿Qué tipo de dátiles prefería el Profeta ﷺ para romper el ayuno?",c:["Dátiles frescos (rutab)","Dátiles secos (tamr)","Higos secos","Pasas"],b:0,e:"Empezaba con dátiles frescos; a falta de ellos, dátiles secos.",s:['h:dattes']}
 ]},
'r-merites':{titre:"Los méritos del ayuno",
 texte:["Allah prescribió el ayuno para que el creyente alcance la piedad (taqwa): la conciencia de Allah en cada acto.",
  "El Profeta ﷺ prometió el perdón de los pecados pasados a quien ayune Ramadán con fe y esperando la recompensa de Allah.",
  "Al final del mes, cada musulmán entrega el zakat al-fitr antes de la oración del Eid. Purifica a quien ayuna y alimenta a los pobres."],
 retenir:"El ayuno lleva a la piedad. El zakat al-fitr se entrega antes de la oración del Eid.",
 sources:['q:2:183','h:pardon','h:fitr'],
 quiz:[
  {q:"Según el Corán, ¿con qué fin prescribió Allah el ayuno?",c:["Para alcanzar la piedad (taqwa)","Solo para purificar el cuerpo","Para conmemorar la Hégira","Para sustituir el zakat"],b:0,e:"La aleya que prescribe el ayuno termina con la esperanza de alcanzar la piedad.",s:['q:2:183']},
  {q:"Según el hadiz, ¿qué gana quien ayuna Ramadán con fe y esperando la recompensa de Allah?",c:["Se le perdonan sus pecados pasados","Ya no necesita rezar","Queda exento del zakat","Nada en particular"],b:0,e:"Se le perdonan sus pecados pasados.",s:['h:pardon']},
  {q:"¿En qué momento hay que entregar el zakat al-fitr?",c:["Antes de la oración del Eid al-Fitr","Un mes después de Ramadán","Solo al comienzo de Ramadán","En cualquier momento del año"],b:0,e:"El Profeta ﷺ ordenó entregarlo antes de que la gente saliera para la oración del Eid.",s:['h:fitr']},
  {q:"¿Qué significa la palabra «taqwa»?",c:["La piedad, la conciencia de Allah","La paciencia (sabr)","La gratitud (shukr)","El arrepentimiento (tawba)"],b:0,e:"La taqwa es el temor reverencial a Allah que impulsa al bien.",s:['q:2:183']},
  {q:"¿Quién debe entregar el zakat al-fitr?",c:["Cada musulmán, pequeño o grande, hombre o mujer","Solo los ricos","Solo los hombres","Solo quienes han ayunado todo el mes"],b:0,e:"El hadiz lo prescribe a cada musulmán; el cabeza de familia lo entrega por los suyos.",s:['h:fitr']},
  {q:"¿Qué cantidad de alimento fija el hadiz para el zakat al-fitr?",c:["Un sa","Un mizqal de oro","Un mudd de trigo","Un dírham de plata"],b:0,e:"Un sa es una medida de unas cuatro veces el hueco de las dos manos juntas.",s:['h:fitr']},
  {q:"¿Qué alimentos se mencionan en el hadiz del zakat al-fitr transmitido por Ibn Umar?",c:["Dátiles o cebada","Arroz o cuscús","Carne o pescado","Leche o miel"],b:0,e:"Un sa de dátiles o un sa de cebada.",s:['h:fitr']},
  {q:"Según el hadiz, ¿con qué condiciones borra el ayuno de Ramadán los pecados pasados?",c:["Con fe y esperando la recompensa de Allah","Ayunando en silencio","Ayunando 40 días","Sin ninguna condición"],b:0,e:"Hay que ayunar con fe y esperando la recompensa de Allah.",s:['h:pardon']},
  {q:"¿Cuál es el fin del zakat al-fitr, según el hadiz de Ibn Abbás?",c:["Purificar a quien ayuna y alimentar a los pobres","Financiar la construcción de mezquitas","Sustituir el ayuno de los enfermos","Recompensar al imam de las tarawih"],b:0,e:"Purifica a quien ayuna de sus palabras vanas y alimenta a los pobres.",s:['h:fitr_but']},
  {q:"¿Con qué llamada comienza la aleya que prescribe el ayuno de Ramadán?",c:["«¡Oh, creyentes!»","«¡Oh, gentes!»","«¡Oh, Profeta!»","«¡Oh, hijos de Adán!»"],b:0,e:"La aleya 183 de la sura Al-Baqara comienza con «¡Oh, creyentes!».",s:['q:2:183']}
 ]},
'r-nuits':{titre:"Las noches de Ramadán",
 texte:["Las noches de Ramadán son la ocasión de rezar más. Su oración nocturna se llama tarawih. El Profeta ﷺ prometió el perdón a quien rece en las noches de Ramadán con fe y esperando la recompensa.",
  "Durante las diez últimas noches redoblaba sus esfuerzos: velaba la noche en oración y despertaba a su familia.",
  "También hacía el itikaf: un retiro espiritual en la mezquita durante los diez últimos días, y lo hizo hasta el final de su vida."],
 retenir:"Tarawih, diez últimas noches, itikaf: las noches de Ramadán se viven en oración.",
 sources:['h:qiyam','h:dixnuits','h:itikaf'],
 quiz:[
  {q:"¿Cómo se llama la oración nocturna que se practica durante Ramadán?",c:["Las tarawih","La oración del Duha","La oración de istijara","La oración fúnebre"],b:0,e:"Las tarawih son la oración de las noches de Ramadán.",s:['h:qiyam']},
  {q:"Según el hadiz, ¿qué gana quien reza en las noches de Ramadán con fe y esperando la recompensa?",c:["Se le perdonan sus pecados pasados","Un lugar en la primera fila de la mezquita","Ya no tiene que ayunar","Nada en particular"],b:0,e:"Se le perdonan sus pecados pasados.",s:['h:qiyam']},
  {q:"¿Qué es el itikaf?",c:["Un retiro espiritual en la mezquita","Un viaje a La Meca","El ayuno de Ashura","Una limosna"],b:0,e:"Uno permanece en la mezquita para dedicarse a la adoración.",s:['h:itikaf']},
  {q:"¿Durante qué periodo de Ramadán hacía el Profeta ﷺ el itikaf?",c:["Los diez últimos días","Los diez primeros días","Solo el primer día","Después del Eid"],b:0,e:"Lo hacía durante los diez últimos días de Ramadán.",s:['h:itikaf']},
  {q:"¿Qué hacía el Profeta ﷺ durante las diez últimas noches de Ramadán?",c:["Velaba en oración y despertaba a su familia","Viajaba","Se acostaba más temprano","Dejaba de ayunar"],b:0,e:"Redoblaba sus esfuerzos en la adoración.",s:['h:dixnuits']},
  {q:"¿Hizo el Profeta ﷺ el itikaf hasta el final de su vida?",c:["Sí, hasta su muerte","No, una sola vez","No, nunca","Solo en La Meca"],b:0,e:"Aisha relata que lo practicó hasta que Allah lo llamó a Su lado.",s:['h:itikaf']},
  {q:"¿Dónde se hace el itikaf?",c:["En la mezquita","En casa","En la cueva de Hira","En el cementerio"],b:0,e:"El Corán menciona a quienes están en retiro en las mezquitas.",s:['q:2:187']},
  {q:"¿Qué noche muy importante se encuentra entre las diez últimas noches de Ramadán?",c:["Laylat al-Qadr, la Noche del Decreto","La noche de la Hégira","La noche del Eid al-Adha","La noche del Mawlid"],b:0,e:"Hay que buscarla en las noches impares de las diez últimas noches.",s:['h:qadr']},
  {q:"¿Es obligatoria la oración de tarawih?",c:["No, es una oración voluntaria muy recomendada","Sí, como las cinco oraciones","Sí, pero solo en la mezquita","Está prohibida"],b:0,e:"El Profeta ﷺ la rezó en grupo algunas noches y luego dejó de hacerlo por temor a que se volviera obligatoria.",s:['h:tarawih']},
  {q:"¿Por qué dejó el Profeta ﷺ de dirigir las tarawih en grupo después de algunas noches?",c:["Por temor a que se volvieran obligatorias","Porque estaba enfermo","Porque la mezquita era demasiado pequeña","Porque Ramadán había terminado"],b:0,e:"Temía que se hicieran obligatorias para su comunidad.",s:['h:tarawih']}
 ]},
'r-qadr':{titre:"Laylat al-Qadr, la Noche del Decreto",
 texte:["Laylat al-Qadr, la Noche del Decreto, es la noche en que comenzó la revelación del Corán.",
  "Allah dice que es «mejor que mil meses». Los ángeles descienden en ella, y es paz hasta el alba. Una sura entera le está dedicada: la sura Al-Qadr (97).",
  "Se la busca en las diez últimas noches de Ramadán, sobre todo en las noches impares, multiplicando las oraciones y las súplicas."],
 retenir:"Mejor que mil meses. Hay que buscarla en las noches impares de las diez últimas noches.",
 sources:['q:97:1','q:97:3','h:qadr'],
 quiz:[
  {q:"Según el Corán, ¿mejor que cuánto tiempo es la Noche del Decreto (Laylat al-Qadr)?",c:["Mil meses","Cien días","Un año","Diez noches"],b:0,e:"Es mejor que mil meses, es decir, más de 83 años.",s:['q:97:3']},
  {q:"¿Qué sura del Corán está dedicada a la Noche del Decreto (Laylat al-Qadr)?",c:["Al-Qadr","Al-Fatiha","Al-Ijlas","Ya-Sin"],b:0,e:"La sura 97, Al-Qadr, lleva el nombre de esta noche.",s:['q:97:1']},
  {q:"¿En qué noches de Ramadán hay que buscar prioritariamente la Noche del Decreto (Laylat al-Qadr)?",c:["Las noches impares de las diez últimas noches","Las diez primeras noches","La primera noche","La noche del Eid"],b:0,e:"Las noches impares de las diez últimas: 21, 23, 25, 27 y 29.",s:['h:qadr']},
  {q:"¿Qué acontecimiento tuvo lugar durante la Noche del Decreto (Laylat al-Qadr)?",c:["El comienzo de la revelación del Corán","La Hégira a Medina","El nacimiento del Profeta ﷺ","La primera peregrinación"],b:0,e:"La revelación del Corán comenzó durante esta noche.",s:['q:97:1']},
  {q:"Según la sura Al-Qadr, ¿quién desciende durante la Noche del Decreto?",c:["Los ángeles y el Espíritu (Yibril)","Los profetas","Los yinn","Nadie"],b:0,e:"Los ángeles y el Espíritu descienden en ella, con el permiso de su Señor.",s:['q:97:4']},
  {q:"Según la sura Al-Qadr, ¿hasta cuándo es paz la Noche del Decreto?",c:["Hasta la aparición del alba","Hasta medianoche","Hasta el final de Ramadán","Hasta el Eid"],b:0,e:"«Es paz hasta la aparición del alba.»",s:['q:97:5']},
  {q:"¿Cuántas aleyas tiene la sura Al-Qadr?",c:["5","7","3","10"],b:0,e:"La sura Al-Qadr tiene 5 aleyas.",s:['q:97:5']},
  {q:"¿Aproximadamente cuántos años representan mil meses?",c:["Más de 83 años","10 años","40 años","1000 años"],b:0,e:"1000 meses ÷ 12 ≈ 83 años y 4 meses: más que una vida entera.",s:['q:97:3']},
  {q:"¿Cuáles son las noches impares de las diez últimas noches de Ramadán?",c:["21, 23, 25, 27 y 29","20, 22, 24, 26 y 28","1, 3, 5, 7 y 9","11, 13, 15, 17 y 19"],b:0,e:"Son las noches recomendadas para buscar Laylat al-Qadr.",s:['h:qadr']},
  {q:"¿Qué súplica enseñó el Profeta ﷺ a Aisha para la Noche del Decreto?",c:["«Allâhumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿannî»","«Bismi Llâh»","«Allâhu akbar»","«Subḥâna Llâh»"],b:0,e:"«Oh Allah, Tú eres el que perdona, amas el perdón, así que perdóname.»",s:['h:afw']}
 ]},
'r-aid':{titre:"El Eid al-Fitr",
 texte:["El Eid al-Fitr es la fiesta de la ruptura del ayuno. Tiene lugar el 1.er día del mes de Shawwal, justo después de Ramadán.",
  "Antes de salir para la oración del Eid, el Profeta ﷺ comía algunos dátiles, en número impar. El zakat al-fitr debe entregarse antes de esta oración.",
  "Después del Eid, se recomienda ayunar seis días del mes de Shawwal: junto con Ramadán, es como ayunar todo el año."],
 retenir:"1 de Shawwal: el Eid. Dátiles antes de la oración y luego seis días de Shawwal.",
 sources:['h:aid_dattes','h:shawwal','q:2:185'],
 quiz:[
  {q:"¿Qué día tiene lugar el Eid al-Fitr?",c:["El 1.er día de Shawwal","El 27 de Ramadán","El 10 de Dhul-Hiyya","El 1 de Muharram"],b:0,e:"El Eid al-Fitr sigue directamente al mes de Ramadán.",s:['f:mois']},
  {q:"¿Qué significa «Eid al-Fitr»?",c:["La fiesta de la ruptura del ayuno","La fiesta del sacrificio","La fiesta de la Hégira","La fiesta del nacimiento del Profeta ﷺ"],b:0,e:"Fitr significa la ruptura del ayuno.",s:['f:aid']},
  {q:"¿Qué comía el Profeta ﷺ antes de salir para la oración del Eid al-Fitr?",c:["Algunos dátiles","Higos","Carne","Nada, ayunaba"],b:0,e:"No salía el día del Eid al-Fitr sin haber comido algunos dátiles.",s:['h:aid_dattes']},
  {q:"¿En qué número comía el Profeta ﷺ los dátiles la mañana del Eid al-Fitr?",c:["En número impar","Siempre dos","Siempre siete","En número par"],b:0,e:"Anas relata que los comía en número impar.",s:['h:aid_dattes']},
  {q:"¿Cuántas fiestas (Eid) tiene el islam en el año?",c:["2","1","3","5"],b:0,e:"El Eid al-Fitr y el Eid al-Adha.",s:['f:aid']},
  {q:"Según el hadiz, ¿cuántos días de Shawwal se recomienda ayunar después de Ramadán?",c:["6","3","10","30"],b:0,e:"Seis días de Shawwal, seguidos o no.",s:['h:shawwal']},
  {q:"Según el hadiz, ¿a qué equivale ayunar Ramadán y después seis días de Shawwal?",c:["A ayunar todo el año","A hacer el hajj","A ayunar un mes más","A nada en particular"],b:0,e:"Es como si hubiera ayunado todo el año.",s:['h:shawwal']},
  {q:"¿Antes de qué oración hay que haber entregado el zakat al-fitr?",c:["La oración del Eid","La oración del viernes","La oración del Maghrib","Las tarawih"],b:0,e:"Debe entregarse antes de que la gente salga para la oración del Eid.",s:['h:fitr']},
  {q:"Según la aleya 185 de la sura Al-Baqara, ¿qué hacen los creyentes una vez completado el número de días de Ramadán?",c:["Proclaman la grandeza de Allah","Vuelven a empezar a ayunar","Hacen el itikaf","Se van a visitar Medina"],b:0,e:"La aleya invita a proclamar la grandeza de Allah por la guía recibida: es el takbir del Eid.",s:['q:2:185']},
  {q:"¿Cuál es la otra gran fiesta del islam, celebrada durante la peregrinación?",c:["El Eid al-Adha","El Eid al-Fitr","El Mawlid","El 1 de Muharram"],b:0,e:"El Eid al-Adha, la fiesta del sacrificio, tiene lugar el 10 de Dhul-Hiyya.",s:['f:aid']}
 ]},

/* ===================== PILARES Y ORACIÓN ===================== */
'p-piliers':{titre:"Los cinco pilares del islam",
 texte:["El islam se basa en cinco pilares, citados en un hadiz auténtico transmitido por al-Bujari y Muslim.",
  "La shahada, el testimonio de fe. El salat, las cinco oraciones diarias. El zakat, la limosna obligatoria. El hajj, la peregrinación a La Meca para quien tiene los medios. El sawm, el ayuno de Ramadán.",
  "Estos cinco pilares son los cimientos de la práctica del musulmán, durante todo el año."],
 retenir:"Shahada, salat, zakat, hajj, ayuno de Ramadán.",
 sources:['h:piliers'],
 quiz:[
  {q:"¿Cuántos pilares tiene el islam?",c:["5","3","4","6"],b:0,e:"El islam se basa en cinco pilares.",s:['h:piliers']},
  {q:"¿Cómo se llama el ayuno en árabe?",c:["Sawm (o siyam)","Salat","Zakat","Hajj"],b:0,e:"El ayuno se dice sawm o siyam; es la palabra de la aleya que lo prescribe.",s:['q:2:183']},
  {q:"¿Para quién es obligatoria la peregrinación a La Meca (hajj)?",c:["Para quien tiene los medios, una vez en la vida","Para todo el mundo, cada año","Solo para los hombres","Solo durante Ramadán"],b:0,e:"El hajj es obligatorio una vez en la vida para quien tiene la capacidad física y económica.",s:['q:3:97']},
  {q:"¿Cuántas oraciones obligatorias realiza un musulmán cada día?",c:["5","3","7","2"],b:0,e:"Fajr, Dhuhr, Asr, Maghrib e Isha.",s:['h:cinq']},
  {q:"¿Cuál es el primer pilar del islam?",c:["La shahada, el testimonio de fe","El ayuno","El hajj","El zakat"],b:0,e:"La shahada se cita en primer lugar en el hadiz.",s:['h:piliers']},
  {q:"¿Qué pilar del islam es la limosna obligatoria?",c:["El zakat","El salat","El sawm","La shahada"],b:0,e:"El zakat se entrega cada año sobre los bienes que alcanzan un umbral.",s:['h:piliers']},
  {q:"¿Qué pilar del islam se practica durante el mes de Ramadán?",c:["El ayuno (sawm)","El hajj","El zakat","La shahada"],b:0,e:"El ayuno de Ramadán es uno de los cinco pilares.",s:['h:piliers']},
  {q:"¿Qué pilar del islam consiste en ir a La Meca?",c:["El hajj","El salat","El sawm","El zakat"],b:0,e:"El hajj es la peregrinación a la Casa sagrada.",s:['q:3:97']},
  {q:"Según el hadiz, ¿cuántas veces en la vida es obligatorio el hajj?",c:["Una sola vez","Cada año","Tres veces","Siete veces"],b:0,e:"El Profeta ﷺ precisó que no era obligatorio cada año.",s:['h:hajj_une']},
  {q:"¿Qué compañero transmitió el hadiz de los cinco pilares del islam?",c:["Abdallah ibn Umar","Abu Bakr","Bilal","Jalid ibn al-Walid"],b:0,e:"El hadiz lo transmite Ibn Umar.",s:['h:piliers']}
 ]},
'p-shahada':{titre:"La shahada, el testimonio de fe",
 texte:["La shahada es el testimonio de fe: «Ash-hadu an lâ ilâha illâ Llâh, wa ash-hadu anna Muḥammadan rasûlu Llâh».",
  "Significa: «Atestiguo que no hay más divinidad que Allah, y atestiguo que Muhammad es el Mensajero de Allah.»",
  "Es el primer pilar: por ella se entra en el islam. Afirma la unicidad de Allah, el tawhid, resumida en la sura Al-Ijlas."],
 retenir:"Lâ ilâha illâ Llâh, Muḥammadun rasûlu Llâh.",
 sources:['q:47:19','q:48:29','h:piliers'],
 quiz:[
  {q:"¿Qué pilar del islam es el testimonio de fe?",c:["La shahada","El salat","El zakat","El hajj"],b:0,e:"La shahada es el primer pilar.",s:['h:piliers']},
  {q:"¿Qué significa «lâ ilâha illâ Llâh»?",c:["No hay más divinidad que Allah","Allah es el más grande","Gloria a Allah","En el nombre de Allah"],b:0,e:"Es la primera parte de la shahada.",s:['q:47:19']},
  {q:"¿Qué significa «Muḥammadun rasûlu Llâh»?",c:["Muhammad es el Mensajero de Allah","Muhammad es un ángel","Muhammad es el primer hombre","Muhammad es un rey"],b:0,e:"Es la segunda parte de la shahada.",s:['q:48:29']},
  {q:"¿Cómo se llama la creencia en la unicidad de Allah?",c:["El tawhid","El hajj","La sunna","El fiqh"],b:0,e:"El tawhid es el corazón de la fe musulmana.",s:['q:112:1']},
  {q:"¿Qué sura resume la unicidad de Allah en cuatro aleyas?",c:["Al-Ijlas","Al-Fatiha","Al-Kawzar","An-Nas"],b:0,e:"La sura 112, Al-Ijlas.",s:['q:112:1']},
  {q:"¿De cuántas partes se compone la shahada?",c:["Dos: la unicidad de Allah y el mensaje de Muhammad ﷺ","Una sola","Cinco","Siete"],b:0,e:"Se atestigua la unicidad de Allah y luego que Muhammad ﷺ es Su Mensajero.",s:['h:piliers']},
  {q:"Según la sura Al-Ijlas, ¿ha engendrado Allah o ha sido engendrado?",c:["Ni lo uno ni lo otro","Las dos cosas","Ha engendrado","Ha sido engendrado"],b:0,e:"«No ha engendrado ni ha sido engendrado.»",s:['q:112:3']},
  {q:"¿Qué significa «Ash-hadu» al comienzo de la shahada?",c:["Atestiguo","Rezo","Ayuno","Perdono"],b:0,e:"Ash-hadu significa «atestiguo, doy testimonio».",s:['f:shahada']},
  {q:"¿Qué hace una persona para entrar en el islam?",c:["Pronuncia la shahada con convicción","Ayuna un mes","Hace el hajj","Aprende árabe"],b:0,e:"La shahada pronunciada sinceramente hace entrar en el islam.",s:['f:shahada']},
  {q:"¿Qué dice el Corán de Muhammad ﷺ en la sura Al Imran, aleya 144?",c:["Que no es más que un mensajero y que otros mensajeros pasaron antes que él","Que es eterno","Que es un ángel","Que es el primer profeta"],b:0,e:"Muhammad ﷺ es un ser humano y un mensajero, como los que lo precedieron.",s:['q:3:144']}
 ]},
'p-priere':{titre:"La oración, cinco citas al día",
 texte:["El musulmán reza cinco veces al día: Fajr al alba, Dhuhr a mediodía, Asr por la tarde, Maghrib a la puesta del sol e Isha por la noche.",
  "Cada oración tiene un número preciso de unidades (rakat): 2 para el Fajr, 4 para el Dhuhr, 4 para el Asr, 3 para el Maghrib y 4 para el Isha.",
  "Se reza orientado hacia la Kaaba, en La Meca: es la qibla. La hora de cada oración se anuncia con el adhan. El viernes, la oración del Dhuhr se sustituye por la oración del viernes (Yumua)."],
 retenir:"Fajr 2, Dhuhr 4, Asr 4, Maghrib 3, Isha 4, orientado hacia la qibla.",
 sources:['q:4:103','f:rakat','q:2:144'],
 quiz:[
  {q:"¿Cuántas unidades (rakat) tiene la oración obligatoria del Fajr?",c:["2","3","4","1"],b:0,e:"La oración del Fajr tiene 2 rakat.",s:['f:rakat']},
  {q:"¿Cuántas unidades (rakat) tiene la oración obligatoria del Maghrib?",c:["3","2","4","5"],b:0,e:"El Maghrib es la única oración obligatoria de 3 rakat.",s:['f:rakat']},
  {q:"¿Hacia qué dirección se orientan los musulmanes para rezar?",c:["Hacia la Kaaba, en La Meca","Hacia Jerusalén","Hacia Medina","Hacia el este"],b:0,e:"Esta dirección se llama qibla.",s:['q:2:144']},
  {q:"¿Cómo se llama la llamada que anuncia la hora de la oración?",c:["El adhan","La iqama","La dua","El dhikr"],b:0,e:"El adhan anuncia la hora; la iqama anuncia el comienzo de la oración en grupo.",s:['h:adhan']},
  {q:"¿Cómo se llama la oración obligatoria que se hace al alba?",c:["El Fajr","El Dhuhr","El Asr","El Isha"],b:0,e:"El Fajr se reza entre el alba y la salida del sol.",s:['f:rakat']},
  {q:"¿Cuántas unidades (rakat) tiene la oración obligatoria del Dhuhr?",c:["4","2","3","5"],b:0,e:"El Dhuhr tiene 4 rakat.",s:['f:rakat']},
  {q:"¿Cuántas unidades (rakat) obligatorias hay en total en las cinco oraciones de un día?",c:["17","15","20","12"],b:0,e:"2 + 4 + 4 + 3 + 4 = 17 rakat.",s:['f:rakat']},
  {q:"Según el Corán, ¿cómo fue prescrita la oración a los creyentes?",c:["En horas determinadas","Una vez por semana","Cuando uno quiera","Solo durante Ramadán"],b:0,e:"«La oración es, para los creyentes, una prescripción en tiempos determinados.»",s:['q:4:103']},
  {q:"¿Qué oración colectiva tiene lugar cada viernes en lugar del Dhuhr?",c:["La oración del viernes (Yumua)","La oración del Eid","Las tarawih","La oración para pedir la lluvia"],b:0,e:"El Corán llama a acudir al recuerdo de Allah el viernes.",s:['q:62:9']},
  {q:"Según el hadiz, ¿durante qué acontecimiento se prescribieron las cinco oraciones?",c:["El Viaje nocturno (al-Isra wal-Miray)","La batalla de Badr","La Hégira","La conquista de La Meca"],b:0,e:"Se prescribieron cincuenta oraciones, que luego se redujeron a cinco.",s:['h:cinq']}
 ]},
'p-ablutions':{titre:"La ablución y la Fatiha",
 texte:["Antes de rezar, el musulmán se purifica con agua: es la ablución (wudu). Sin agua, se hace el tayammum con tierra limpia.",
  "Se lavan la cara, las manos y los antebrazos hasta los codos, se pasan las manos mojadas por la cabeza y luego se lavan los pies hasta los tobillos.",
  "En cada unidad de la oración se recita la sura Al-Fatiha, «la Apertura», la primera sura del Corán, que tiene 7 aleyas."],
 retenir:"No hay oración sin ablución, no hay oración sin la Fatiha.",
 sources:['q:5:6','q:1:2','h:fatiha'],
 quiz:[
  {q:"¿Cómo se llama la purificación que se hace con agua antes de la oración?",c:["La ablución (wudu)","El ayuno","El zakat","El itikaf"],b:0,e:"El wudu purifica antes de la oración.",s:['q:5:6']},
  {q:"¿Qué sura se recita en cada unidad (raka) de la oración?",c:["Al-Fatiha","Al-Ijlas","Al-Baqara","Ya-Sin"],b:0,e:"Al-Fatiha, «la Apertura», se recita en cada raka.",s:['h:fatiha']},
  {q:"¿Con qué frase comienza la sura Al-Fatiha?",c:["Bismi Llâhi r-Raḥmâni r-Raḥîm","Qul huwa Llâhu aḥad","Allâhu akbar","Subḥâna Llâh"],b:0,e:"«En el nombre de Allah, el Compasivo, el Misericordioso.»",s:['q:1:1']},
  {q:"Según el Corán, ¿hasta dónde se lavan los brazos durante la ablución?",c:["Hasta los codos","Hasta las muñecas","Hasta los hombros","Solo los dedos"],b:0,e:"La aleya 6 de la sura Al-Maida lo precisa.",s:['q:5:6']},
  {q:"Según el Corán, ¿qué se hace con la cabeza durante la ablución?",c:["Se pasan las manos mojadas por ella","Se lava entera tres veces","Se cubre con un turbante","Se echa agua en la nuca"],b:0,e:"Es el mash: pasar las manos mojadas por la cabeza.",s:['q:5:6']},
  {q:"¿Qué se hace cuando no se encuentra agua para purificarse antes de la oración?",c:["El tayammum, con tierra limpia","No se reza","Se espera al día siguiente","Se reza sin purificación"],b:0,e:"La misma aleya prevé el tayammum cuando falta el agua.",s:['q:5:6']},
  {q:"Según el hadiz, ¿acepta Allah la oración de quien ha perdido la ablución sin renovarla?",c:["No, no hasta que renueve la ablución","Sí, siempre","Sí, el viernes","Solo la oración del Fajr"],b:0,e:"La oración solo se acepta después de haber renovado la ablución.",s:['h:wudu']},
  {q:"¿Cuántas aleyas tiene la sura Al-Fatiha?",c:["7","5","10","3"],b:0,e:"Se la llama «las siete aleyas repetidas».",s:['q:15:87']},
  {q:"¿Qué significa «Al-ḥamdu li-Llâhi rabbi l-ʿâlamîn»?",c:["Alabado sea Allah, Señor del universo","Allah es el más grande","No hay más divinidad que Allah","Busco refugio en Allah"],b:0,e:"Es la 2.ª aleya de la Fatiha.",s:['q:1:2']},
  {q:"Según el hadiz, ¿qué vale la oración de quien no recita la Fatiha?",c:["No es válida","Cuenta doble","Es válida","Cuenta a medias"],b:0,e:"«No hay oración para quien no recita la Fatiha.»",s:['h:fatiha']}
 ]},
'p-zakat':{titre:"El zakat, la limosna obligatoria",
 texte:["El zakat es la limosna obligatoria, uno de los cinco pilares del islam. Su nombre evoca la purificación y el crecimiento: purifica los bienes y ayuda a los más necesitados.",
  "Concierne a quien tiene ahorros que alcanzan un umbral mínimo (el nisab) y permanecen en su poder durante un año lunar completo. Para el dinero, es del 2,5 %.",
  "El Corán cita ocho categorías de beneficiarios, entre ellos los pobres y los necesitados. La sadaqa, en cambio, es una limosna voluntaria, posible en cualquier momento."],
 retenir:"Zakat: 2,5 % de los ahorros que alcanzan el nisab durante un año lunar.",
 sources:['q:9:60','q:9:103','f:zakat'],
 quiz:[
  {q:"¿Qué pilar del islam es la limosna obligatoria?",c:["El zakat","La sadaqa","El hajj","El sawm"],b:0,e:"El zakat es obligatorio; la sadaqa es voluntaria.",s:['h:piliers']},
  {q:"¿Cuál es el porcentaje del zakat sobre el dinero ahorrado?",c:["2,5 %","10 %","20 %","5 %"],b:0,e:"Es decir, una cuarentava parte de los ahorros.",s:['f:zakat']},
  {q:"¿Cómo se llama el umbral mínimo de riqueza a partir del cual se debe el zakat?",c:["El nisab","El sa","La fidya","El hawl"],b:0,e:"Por debajo del nisab, el zakat no es obligatorio.",s:['f:zakat']},
  {q:"¿Durante cuánto tiempo hay que poseer los ahorros para que se deba el zakat?",c:["Un año lunar","Un mes","Diez años","Solo el mes de Ramadán"],b:0,e:"Es el hawl: un año lunar completo.",s:['f:zakat']},
  {q:"Según el Corán, ¿cuántas categorías de personas pueden recibir el zakat?",c:["8","5","3","12"],b:0,e:"La aleya 60 de la sura At-Tawba cita ocho.",s:['q:9:60']},
  {q:"¿Quiénes forman parte de los beneficiarios del zakat citados en el Corán?",c:["Los pobres y los necesitados","Los más ricos","Los comerciantes","Los imames de las mezquitas"],b:0,e:"Los pobres y los necesitados se citan en primer lugar.",s:['q:9:60']},
  {q:"¿Cuál es la diferencia entre el zakat y la sadaqa?",c:["El zakat es obligatorio, la sadaqa es voluntaria","No hay ninguna","La sadaqa es obligatoria","El zakat está prohibido"],b:0,e:"La sadaqa puede darse en cualquier momento y en cualquier cantidad.",s:['f:zakat']},
  {q:"En el Corán, ¿con qué acto se cita muy a menudo el zakat?",c:["La oración","El ayuno","La peregrinación","La ablución"],b:0,e:"«Estableced la oración y entregad el zakat»: la fórmula se repite muchas veces.",s:['q:2:43']},
  {q:"En el orden del hadiz de los pilares, ¿en qué lugar aparece el zakat?",c:["El 3.º","El 1.º","El 5.º","El 2.º"],b:0,e:"Shahada, oración, zakat, hajj, ayuno de Ramadán.",s:['h:piliers']},
  {q:"¿Qué evoca la palabra «zakat» en árabe?",c:["La purificación y el crecimiento","La paciencia","La victoria","La luz"],b:0,e:"El Corán dice que la limosna purifica (tutahhiruhum) y hace crecer en el bien (tuzakkihim).",s:['q:9:103']}
 ]},
'p-hajj':{titre:"El hajj, la peregrinación",
 texte:["El hajj es la peregrinación a La Meca, uno de los cinco pilares del islam. Es obligatorio una vez en la vida para quien tiene los medios físicos y económicos.",
  "Tiene lugar durante el mes de Dhul-Hiyya. El peregrino entra en estado de sacralización (ihram), da siete vueltas alrededor de la Kaaba (tawaf) y hace siete recorridos entre Safa y Marwa (sai). El momento más importante es la permanencia en Arafa, el 9 de Dhul-Hiyya.",
  "Al día siguiente, los musulmanes del mundo entero celebran el Eid al-Adha, la fiesta del sacrificio, en recuerdo de Ibrahim."],
 retenir:"Una vez en la vida. Arafa el 9 de Dhul-Hiyya, el Eid al-Adha el 10.",
 sources:['q:3:97','q:22:27','h:hajj_pardon'],
 quiz:[
  {q:"¿En qué ciudad se hace el hajj?",c:["La Meca","Medina","Jerusalén","Taif"],b:0,e:"El hajj se hace en La Meca y sus alrededores.",s:['q:3:97']},
  {q:"¿Durante qué mes del calendario musulmán tiene lugar el hajj?",c:["Dhul-Hiyya","Ramadán","Muharram","Shawwal"],b:0,e:"El hajj se desarrolla del 8 al 13 de Dhul-Hiyya.",s:['f:hajj']},
  {q:"Según el hadiz, ¿cuál es el elemento más importante del hajj?",c:["La permanencia en Arafa","La oración en la mezquita al-Aqsa","La visita a Medina","La visita a la cueva de Hira"],b:0,e:"«El hajj es Arafa.»",s:['h:arafa']},
  {q:"¿Qué fiesta se celebra el día siguiente al día de Arafa?",c:["El Eid al-Adha","El Eid al-Fitr","El Mawlid","El 1 de Muharram"],b:0,e:"El 10 de Dhul-Hiyya es el Eid al-Adha.",s:['f:hajj']},
  {q:"Según el hadiz, ¿cómo vuelve el peregrino que realiza el hajj sin pecado ni groserías?",c:["Como el día en que su madre lo dio a luz","Más rico","Exento de ayunar","Con el título de hayy, sin otra recompensa"],b:0,e:"Vuelve limpio de sus pecados.",s:['h:hajj_pardon']},
  {q:"¿Qué profeta recibió la orden de llamar a la gente a la peregrinación?",c:["Ibrahim","Musa","Nuh","Yusuf"],b:0,e:"Allah ordenó a Ibrahim llamar a la gente al hajj.",s:['q:22:27']},
  {q:"¿Cómo se llama el estado de sacralización en el que entra el peregrino?",c:["El ihram","El wudu","El itikaf","El tayammum"],b:0,e:"Los hombres llevan dos piezas de tela blanca sin costuras.",s:['f:hajj']},
  {q:"¿Cómo se llaman las siete vueltas que se dan alrededor de la Kaaba?",c:["El tawaf","El sai","La raka","El dhikr"],b:0,e:"El tawaf se hace en siete vueltas, con la Kaaba a la izquierda.",s:['f:hajj']},
  {q:"¿Entre qué dos colinas hace el peregrino siete recorridos?",c:["Safa y Marwa","Arafa y Mina","Uhud y Zawr","Hira y Zawr"],b:0,e:"El Corán cita Safa y Marwa entre los ritos de Allah.",s:['q:2:158']},
  {q:"¿En recuerdo de qué profeta sacrifican los musulmanes un animal el día del Eid al-Adha?",c:["Ibrahim","Isa","Musa","Daud"],b:0,e:"Allah rescató al hijo de Ibrahim con un sacrificio generoso.",s:['q:37:107']}
 ]},

/* ===================== CORÁN ===================== */
'c-coran':{titre:"El Corán, palabra de Allah",
 texte:["El Corán es la palabra de Allah, revelada en árabe al Profeta Muhammad ﷺ por medio del ángel Yibril (Gabriel).",
  "La primera revelación tuvo lugar en la cueva de Hira, cerca de La Meca, cuando el Profeta ﷺ tenía 40 años. Las primeras palabras reveladas comienzan con «Iqra'»: «¡Lee!».",
  "La revelación duró unos 23 años. El Corán tiene 114 suras; Allah se comprometió a preservarlo."],
 retenir:"114 suras, reveladas en 23 años. Primera palabra: «Iqra'», «¡Lee!».",
 sources:['q:96:1','h:hira','q:15:9'],
 quiz:[
  {q:"¿Cuántas suras tiene el Corán?",c:["114","99","120","30"],b:0,e:"El Corán tiene 114 suras.",s:['f:coran']},
  {q:"¿Qué ángel transmitió el Corán al Profeta Muhammad ﷺ?",c:["Yibril (Gabriel)","Mikail","Israfil","Malik"],b:0,e:"Fue el ángel Yibril quien transmitió la revelación.",s:['q:2:97']},
  {q:"¿En qué cueva recibió el Profeta ﷺ la primera revelación del Corán?",c:["La cueva de Hira","La cueva de Zawr","Una cueva de Medina","Una cueva de Jerusalén"],b:0,e:"La cueva de Hira se encuentra en el Yabal an-Nur, cerca de La Meca.",s:['h:hira']},
  {q:"¿Qué significa «Iqra'», la primera palabra revelada del Corán?",c:["¡Lee!","¡Reza!","¡Escucha!","¡Ayuna!"],b:0,e:"Es el comienzo de la sura Al-Alaq (96).",s:['q:96:1']},
  {q:"¿Durante cuántos años aproximadamente fue revelado el Corán?",c:["23 años","1 año","40 años","10 años"],b:0,e:"Unos 13 años en La Meca y 10 años en Medina.",s:['h:vie']},
  {q:"¿En cuántas partes (yuz) se divide el Corán para su lectura?",c:["30","114","7","12"],b:0,e:"Treinta partes: por ejemplo, una al día durante Ramadán.",s:['f:coran']},
  {q:"¿En qué lengua fue revelado el Corán?",c:["En árabe","En hebreo","En persa","En arameo"],b:0,e:"«Lo hemos hecho descender como un Corán en lengua árabe.»",s:['q:12:2']},
  {q:"Según el Corán, ¿quién garantiza la preservación del Corán?",c:["Allah","Solo los sabios","Los califas","Nadie"],b:0,e:"«Somos Nosotros quienes hemos hecho descender el Recuerdo, y somos Nosotros sus guardianes.»",s:['q:15:9']},
  {q:"¿Qué edad tenía el Profeta ﷺ cuando recibió la primera revelación?",c:["40 años","25 años","63 años","13 años"],b:0,e:"Comenzó a recibir la revelación a los 40 años.",s:['h:vie']},
  {q:"¿Cómo se llama en árabe un versículo del Corán?",c:["Una aya","Una sura","Un yuz","Un hadiz"],b:0,e:"Un versículo se dice aya (aleya); un capítulo, sura.",s:['f:coran']}
 ]},
'c-sourates':{titre:"Las suras",
 texte:["El Corán está compuesto por 114 suras de longitudes muy diferentes. Cada una comienza con la basmala, salvo la sura At-Tawba.",
  "La primera es Al-Fatiha, «la Apertura». La más larga es Al-Baqara, «la Vaca», con 286 aleyas. La más corta es Al-Kawzar, con 3 aleyas. La última es An-Nas, «los Hombres».",
  "Las suras reveladas antes de la Hégira se llaman mequíes, y las reveladas después, medinenses."],
 retenir:"Primera: Al-Fatiha. La más larga: Al-Baqara. La más corta: Al-Kawzar. Última: An-Nas.",
 sources:['q:1:1','q:108:1','q:114:1'],
 quiz:[
  {q:"¿Cuál es la primera sura del Corán?",c:["Al-Fatiha","Al-Baqara","An-Nas","Al-Alaq"],b:0,e:"Al-Fatiha abre el Corán. Al-Alaq contiene las primeras aleyas reveladas, pero es la sura 96.",s:['q:1:1']},
  {q:"¿Cuál es la sura más larga del Corán?",c:["Al-Baqara","Al-Fatiha","Al-Kawzar","Ya-Sin"],b:0,e:"Al-Baqara, la sura 2, tiene 286 aleyas.",s:['f:coran']},
  {q:"¿Cuál es la sura más corta del Corán?",c:["Al-Kawzar","Al-Ijlas","An-Nas","Al-Asr"],b:0,e:"Al-Kawzar, la sura 108, tiene 3 aleyas.",s:['q:108:1']},
  {q:"¿Cuál es la última sura del Corán?",c:["An-Nas","Al-Falaq","Al-Ijlas","Al-Fatiha"],b:0,e:"An-Nas, «los Hombres», es la sura 114.",s:['q:114:1']},
  {q:"¿Qué sura comienza con «Qul huwa Llâhu aḥad»?",c:["Al-Ijlas","An-Nas","Al-Falaq","Al-Kafirun"],b:0,e:"«Di: Él es Allah, Uno.»",s:['q:112:1']},
  {q:"¿Qué sura contiene la aleya «Ese es el Libro sobre el que no hay ninguna duda»?",c:["Al-Baqara","Al-Fatiha","Maryam","Ya-Sin"],b:0,e:"Es la 2.ª aleya de la sura Al-Baqara.",s:['q:2:2']},
  {q:"¿Qué sura lleva el nombre de la madre de Isa (Jesús)?",c:["Maryam","Al Imran","An-Nisa","Ta-Ha"],b:0,e:"La sura 19 lleva el nombre de Maryam.",s:['q:19:16']},
  {q:"¿Cuál es la única sura que no comienza con «Bismi Llâhi r-Raḥmâni r-Raḥîm»?",c:["At-Tawba (sura 9)","Al-Fatiha","An-Nas","Al-Baqara"],b:0,e:"At-Tawba es la única de las 114 suras sin basmala al comienzo.",s:['f:tawba']},
  {q:"¿Cómo se llama la fórmula «Bismi Llâhi r-Raḥmâni r-Raḥîm»?",c:["La basmala","La shahada","El takbir","La talbiya"],b:0,e:"Significa: «En el nombre de Allah, el Compasivo, el Misericordioso».",s:['q:1:1']},
  {q:"¿Cómo se llaman las suras reveladas en La Meca, antes de la Hégira?",c:["Las suras mequíes","Las suras medinenses","Las suras largas","Las suras de Taif"],b:0,e:"Las reveladas después de la Hégira se llaman medinenses.",s:['f:coran']}
 ]},
'c-ikhlas':{titre:"Al-Ijlas y la aleya del Trono",
 texte:["La sura Al-Ijlas (112) resume la fe en la unicidad de Allah: Él es Uno, no ha engendrado ni ha sido engendrado, y nadie es igual a Él.",
  "El Profeta ﷺ dijo que equivale a un tercio del Corán.",
  "La aleya del Trono, Ayat al-Kursi (sura 2, aleya 255), es la aleya más grande del Corán. Describe la vida, el conocimiento y el poder de Allah."],
 retenir:"Al-Ijlas vale un tercio del Corán. Ayat al-Kursi es la aleya más grande.",
 sources:['q:112:1','h:ikhlas','h:kursi'],
 quiz:[
  {q:"¿Qué significa «Qul huwa Llâhu aḥad»?",c:["Di: Él es Allah, Uno","En el nombre de Allah","Allah es el más grande","Gloria a Allah"],b:0,e:"Es la primera aleya de la sura Al-Ijlas.",s:['q:112:1']},
  {q:"Según el hadiz, ¿a qué parte del Corán equivale la sura Al-Ijlas?",c:["Un tercio","La mitad","Una décima parte","El Corán entero"],b:0,e:"El Profeta ﷺ dijo que equivale a un tercio del Corán.",s:['h:ikhlas']},
  {q:"¿Cuántas aleyas tiene la sura Al-Ijlas?",c:["4","7","3","5"],b:0,e:"La sura Al-Ijlas tiene 4 aleyas.",s:['q:112:4']},
  {q:"Según la sura Al-Ijlas, ¿hay alguien igual a Allah?",c:["No, nadie es igual a Él","Sí, los ángeles","Sí, los profetas","Sí, los yinn"],b:0,e:"«Y nadie es igual a Él.»",s:['q:112:4']},
  {q:"Según el hadiz, ¿cuál es la aleya más grande del Corán?",c:["Ayat al-Kursi, la aleya del Trono","La primera aleya de la Fatiha","La última aleya del Corán","La aleya de la luz"],b:0,e:"Ubayy ibn Kab se lo dijo al Profeta ﷺ, que lo aprobó.",s:['h:kursi']},
  {q:"¿En qué sura se encuentra Ayat al-Kursi?",c:["Al-Baqara, aleya 255","Al-Fatiha, aleya 1","Ya-Sin, aleya 1","Al-Ijlas, aleya 2"],b:0,e:"La aleya del Trono es la aleya 255 de la sura Al-Baqara.",s:['q:2:255']},
  {q:"Según Ayat al-Kursi, ¿se apoderan de Allah la somnolencia o el sueño?",c:["No, ni la somnolencia ni el sueño se apoderan de Él","Sí, por la noche","Sí, a veces","Solo el sueño"],b:0,e:"Allah es el Viviente, el que subsiste por Sí mismo.",s:['q:2:255']},
  {q:"¿Qué significa «Allâhu ṣ-ṣamad» en la sura Al-Ijlas?",c:["Allah es Aquel de quien todos necesitan y que no necesita de nadie","Allah es el Creador del cielo","Allah es el Perdonador","Allah es el Juez"],b:0,e:"As-Samad es uno de los nombres de Allah.",s:['q:112:2']},
  {q:"¿Qué significa el nombre de la sura «Al-Ijlas»?",c:["El monoteísmo puro, la sinceridad","El alba","La victoria","Los hombres"],b:0,e:"Purifica la fe de toda asociación.",s:['f:ikhlas']},
  {q:"Según Ayat al-Kursi, ¿qué parte de Su conocimiento concede Allah a Sus criaturas?",c:["Solo lo que Él quiere","Todo Su conocimiento","Nada en absoluto","La mitad"],b:0,e:"«Y no abarcan nada de Su conocimiento salvo lo que Él quiere.»",s:['q:2:255']}
 ]},

/* ===================== PROFETAS ===================== */
'pr-adam':{titre:"Adán y Nuh",
 texte:["Adán es el primer hombre y el primer profeta. Allah le enseñó el nombre de todas las cosas y luego ordenó a los ángeles que se prosternaran ante él. Iblis se negó por orgullo.",
  "Nuh (Noé) llamó a su pueblo a adorar solo a Allah durante 950 años. Poca gente lo siguió, ni siquiera su propio hijo.",
  "Por orden de Allah, Nuh construyó el arca, que lo salvó del diluvio junto con los creyentes y parejas de animales."],
 retenir:"Adán, el primer hombre. Nuh, 950 años de predicación, y el arca.",
 sources:['q:2:31','q:2:34','q:29:14'],
 quiz:[
  {q:"¿Quién es el primer profeta de la humanidad?",c:["Adán","Nuh (Noé)","Ibrahim (Abraham)","Musa (Moisés)"],b:0,e:"Adán es el primer hombre y el primer profeta.",s:['q:2:31']},
  {q:"¿Qué le enseñó Allah a Adán?",c:["El nombre de todas las cosas","El Corán de memoria","Solo la lengua de los ángeles","Solo los nombres de los profetas"],b:0,e:"«Y enseñó a Adán todos los nombres.»",s:['q:2:31']},
  {q:"¿Quién se negó a prosternarse ante Adán?",c:["Iblis","Yibril","Mikail","Todos los ángeles"],b:0,e:"Los ángeles se prosternaron, excepto Iblis.",s:['q:2:34']},
  {q:"¿Por qué se negó Iblis a prosternarse ante Adán?",c:["Por orgullo","Por olvido","Por miedo","Porque no había oído la orden"],b:0,e:"Se negó, se llenó de orgullo y fue de los incrédulos.",s:['q:2:34']},
  {q:"¿Dónde vivían Adán y su esposa antes de descender a la tierra?",c:["En el Paraíso","En La Meca","En Egipto","En Jerusalén"],b:0,e:"«Habita el Paraíso, tú y tu esposa.»",s:['q:2:35']},
  {q:"¿Qué profeta construyó el arca por orden de Allah?",c:["Nuh (Noé)","Yunus (Jonás)","Sulayman (Salomón)","Isa (Jesús)"],b:0,e:"Nuh construyó el arca bajo la mirada de Allah y según Su revelación.",s:['q:11:37']},
  {q:"Según el Corán, ¿cuánto tiempo permaneció Nuh entre su pueblo?",c:["950 años","40 años","100 años","313 años"],b:0,e:"«Mil años menos cincuenta.»",s:['q:29:14']},
  {q:"¿Quiénes se salvaron en el arca de Nuh?",c:["Nuh, los creyentes y parejas de animales","Todo su pueblo","Solo los animales","Nadie"],b:0,e:"Allah ordenó subir a ella una pareja de cada especie, a su familia y a los creyentes.",s:['q:11:40']},
  {q:"¿Subió el hijo de Nuh al arca?",c:["No, se negó y fue tragado por las aguas","Sí, el primero","Sí, al final","No tenía hijos"],b:0,e:"Pensó refugiarse en una montaña, pero las olas se lo llevaron.",s:['q:11:43']},
  {q:"¿Cómo se llama la esposa de Adán, según la tradición musulmana?",c:["Hawwa (Eva)","Maryam","Asiya","Hayar"],b:0,e:"El Corán la menciona sin nombrarla; su nombre procede de la Sunna.",s:['f:hawwa']}
 ]},
'pr-ibrahim':{titre:"Ibrahim, el amigo de Allah",
 texte:["Ibrahim (Abraham) se negó a adorar los ídolos de su pueblo. Lo arrojaron a un gran fuego, pero Allah ordenó al fuego ser frescor y paz para él.",
  "Allah lo tomó como amigo íntimo (jalil). Es el padre de dos profetas: Ismail e Ishaq.",
  "Con su hijo Ismail, levantó los cimientos de la Kaaba. El sacrificio del Eid al-Adha recuerda su obediencia a Allah."],
 retenir:"Ibrahim, el amigo de Allah, salvado del fuego, constructor de la Kaaba con Ismail.",
 sources:['q:21:69','q:4:125','q:2:127'],
 quiz:[
  {q:"¿Qué profeta levantó los cimientos de la Kaaba con su hijo Ismail?",c:["Ibrahim (Abraham)","Musa (Moisés)","Daud (David)","Adán"],b:0,e:"Ibrahim y su hijo Ismail levantaron los cimientos de la Kaaba.",s:['q:2:127']},
  {q:"¿Qué le ocurrió a Ibrahim cuando su pueblo lo arrojó al fuego?",c:["Allah hizo el fuego fresco e inofensivo para él","Huyó","Resultó herido","Lo salvó la lluvia"],b:0,e:"«¡Oh fuego, sé frescor y paz para Ibrahim!»",s:['q:21:69']},
  {q:"¿Qué título da el Corán al profeta Ibrahim?",c:["El amigo íntimo de Allah (Jalil)","El sello de los profetas","Aquel a quien Allah habló","El Espíritu de Allah"],b:0,e:"«Y Allah tomó a Ibrahim como amigo íntimo.»",s:['q:4:125']},
  {q:"¿Cuáles son los dos hijos profetas de Ibrahim?",c:["Ismail e Ishaq","Musa y Harun","Daud y Sulayman","Yahya e Isa"],b:0,e:"Ibrahim agradeció a Allah que le diera a Ismail e Ishaq en su vejez.",s:['q:14:39']},
  {q:"¿Qué hacía el pueblo de Ibrahim que él rechazaba?",c:["Adorar estatuas","Ayunar","Dar limosna","Hacer la peregrinación"],b:0,e:"Les preguntó: «¿Qué son estas estatuas a las que estáis apegados?»",s:['q:21:52']},
  {q:"¿Con qué rescató Allah al hijo de Ibrahim en el momento del sacrificio?",c:["Con un sacrificio generoso (un animal para sacrificar)","Con una limosna de oro","Con el ayuno de su padre","Con una oración nocturna"],b:0,e:"La tradición precisa que se trataba de un carnero.",s:['q:37:107']},
  {q:"¿Qué fiesta recuerda la obediencia de Ibrahim a Allah?",c:["El Eid al-Adha","El Eid al-Fitr","El 1 de Muharram","El Mawlid"],b:0,e:"El sacrificio del Eid al-Adha conmemora su prueba.",s:['q:37:107']},
  {q:"Según el Corán, ¿cómo se describe a Ibrahim?",c:["Un creyente monoteísta (hanif), ni judío ni cristiano","Un rey de Babilonia","Un ángel","Un poeta"],b:0,e:"Estaba totalmente sometido a Allah.",s:['q:3:67']},
  {q:"¿Qué hijo ayudó a Ibrahim a levantar los cimientos de la Kaaba?",c:["Ismail","Ishaq","Yaqub","Yusuf"],b:0,e:"Ibrahim e Ismail levantaban juntos los cimientos de la Casa.",s:['q:2:127']},
  {q:"Según el Corán, ¿cuál es la primera Casa de culto establecida para los hombres?",c:["La de Bakka (La Meca)","La de Jerusalén","La de Medina","La de Taif"],b:0,e:"Bakka es un nombre de La Meca.",s:['q:3:96']}
 ]},
'pr-yunus':{titre:"Yunus, Yusuf y Sulayman",
 texte:["Yunus (Jonás) fue tragado por un gran pez. En las tinieblas invocó a Allah, que lo salvó de la angustia.",
  "La historia de Yusuf (José), traicionado por sus hermanos y luego convertido en ministro en Egipto, ocupa toda la sura 12: «el mejor de los relatos».",
  "Sulayman (Salomón), hijo de Daud, recibió un reino inmenso y comprendía el lenguaje de los pájaros y de las hormigas."],
 retenir:"Yunus y el pez. Yusuf, sura 12. Sulayman y el lenguaje de los animales.",
 sources:['q:37:142','q:12:3','q:27:18'],
 quiz:[
  {q:"¿Qué profeta fue tragado por un gran pez?",c:["Yunus (Jonás)","Yusuf (José)","Ayyub (Job)","Lut (Lot)"],b:0,e:"Yunus fue tragado por el pez y luego Allah lo salvó.",s:['q:37:142']},
  {q:"¿Qué sura del Corán cuenta entera la historia del profeta Yusuf (José)?",c:["La sura 12, Yusuf","La sura 1, Al-Fatiha","La sura 36, Ya-Sin","La sura 112, Al-Ijlas"],b:0,e:"La sura 12 lleva su nombre.",s:['q:12:3']},
  {q:"¿Qué profeta comprendía el lenguaje de las hormigas?",c:["Sulayman (Salomón)","Salih","Hud","Zakariyya"],b:0,e:"Sulayman oyó a una hormiga advertir a las demás y sonrió por sus palabras.",s:['q:27:18']},
  {q:"¿Qué súplica pronunció Yunus en el vientre del pez?",c:["«Lâ ilâha illâ anta, subḥânaka, innî kuntu mina ẓ-ẓâlimîn»","«Bismi Llâh»","«Allâhu akbar»","«Rabbanâ âtinâ»"],b:0,e:"«¡No hay más divinidad que Tú! ¡Gloria a Ti! Ciertamente he sido de los injustos.»",s:['q:21:87']},
  {q:"¿Cómo respondió Allah a la súplica de Yunus?",c:["Lo salvó de la angustia","Lo dejó dentro del pez","Lo dejó tres años dentro del pez","No respondió"],b:0,e:"«Le respondimos y lo salvamos de la angustia.»",s:['q:21:88']},
  {q:"En su sueño de niño, ¿cuántas estrellas vio Yusuf prosternarse ante él?",c:["Once, con el sol y la luna","Siete","Doce","Una sola"],b:0,e:"Once estrellas, el sol y la luna.",s:['q:12:4']},
  {q:"¿Quién arrojó a Yusuf al fondo de un pozo?",c:["Sus hermanos","El Faraón","Unos mercaderes","Su padre"],b:0,e:"Sus hermanos, celosos, decidieron arrojarlo al fondo del pozo.",s:['q:12:15']},
  {q:"¿Cómo llama el Corán a la historia de Yusuf?",c:["El mejor de los relatos","El relato del fuego","El libro de la sabiduría","El relato del arca"],b:0,e:"«Te contamos el mejor de los relatos.»",s:['q:12:3']},
  {q:"¿Qué profeta recibió el conocimiento del lenguaje de los pájaros?",c:["Sulayman","Yunus","Nuh","Hud"],b:0,e:"«Se nos ha enseñado el lenguaje de los pájaros», dijo Sulayman.",s:['q:27:16']},
  {q:"¿Quién era el padre de Sulayman, también profeta y rey?",c:["Daud (David)","Ibrahim","Yaqub","Musa"],b:0,e:"«Y Sulayman heredó a Daud.»",s:['q:27:16']}
 ]},
'pr-musa':{titre:"Musa, aquel a quien Allah habló",
 texte:["Musa (Moisés) nació en Egipto, en la época en que el Faraón perseguía a los Banu Israil. Por inspiración de Allah, su madre lo dejó en el río, y la familia del Faraón lo recogió.",
  "Allah le habló directamente y lo envió al Faraón con su hermano Harun, y con milagros, como su bastón que se convirtió en serpiente.",
  "Allah partió el mar para salvar a Musa y a su pueblo, y el Faraón fue tragado por las aguas. Musa es el profeta más citado en el Corán."],
 retenir:"Musa, salvado de las aguas, Kalim Allah, el mar partido.",
 sources:['q:28:7','q:4:164','q:26:63'],
 quiz:[
  {q:"¿En qué país nació el profeta Musa (Moisés)?",c:["En Egipto","En Arabia","En Irak","En Yemen"],b:0,e:"Nació en Egipto, bajo el reinado del Faraón.",s:['q:28:7']},
  {q:"¿Qué hizo la madre de Musa para protegerlo del Faraón?",c:["Lo dejó en el río","Lo escondió en una cueva","Se marchó al desierto","Lo confió a un pastor"],b:0,e:"Allah le inspiró que lo arrojara al río, sin temor.",s:['q:28:7']},
  {q:"¿Quién recogió del río a Musa cuando era bebé?",c:["La familia del Faraón","Unos pescadores","Ibrahim","Un rey de Yemen"],b:0,e:"La gente del Faraón lo recogió.",s:['q:28:8']},
  {q:"¿Qué profeta es llamado «Kalim Allah», aquel a quien Allah habló directamente?",c:["Musa","Ibrahim","Isa","Nuh"],b:0,e:"«Y Allah habló a Musa directamente.»",s:['q:4:164']},
  {q:"¿En qué se convirtió el bastón de Musa cuando lo arrojó al suelo?",c:["En una serpiente","En un árbol","En una paloma","En una espada"],b:0,e:"«Lo arrojó, y he aquí que era una serpiente que se movía.»",s:['q:20:20']},
  {q:"¿Qué ocurrió cuando Musa golpeó el mar con su bastón?",c:["Se partió en dos","Se convirtió en arena","Se secó de golpe","Nada"],b:0,e:"Cada parte era como una enorme montaña.",s:['q:26:63']},
  {q:"¿Qué les ocurrió al Faraón y a su ejército, que perseguían a Musa?",c:["Fueron tragados por el mar","Se convirtieron","Volvieron a Egipto","También cruzaron"],b:0,e:"Allah salvó a Musa y a quienes estaban con él, e hizo que los demás se ahogaran.",s:['q:26:66']},
  {q:"¿Cómo se llamaba el hermano de Musa, que lo ayudó en su misión?",c:["Harun (Aarón)","Yusuf","Ishaq","Yahya"],b:0,e:"Musa pidió a Allah que le diera a su hermano Harun como ayudante.",s:['q:20:30']},
  {q:"¿A qué rey envió Allah a Musa?",c:["Al Faraón","A Nimrod","Al rey de Saba","A Goliat"],b:0,e:"«Ve al Faraón, pues se ha excedido en todo límite.»",s:['q:20:24']},
  {q:"¿Qué profeta es el más citado por su nombre en el Corán?",c:["Musa","Muhammad ﷺ","Ibrahim","Nuh"],b:0,e:"Musa es nombrado más de 130 veces en el Corán.",s:['f:musa']}
 ]},
'pr-isa':{titre:"Isa y Maryam",
 texte:["Maryam (María), madre de Isa, es la única mujer nombrada en el Corán. Allah la eligió por encima de las mujeres de los mundos, y una sura lleva su nombre.",
  "Isa (Jesús) nació sin padre, por voluntad de Allah, como Adán fue creado sin padre ni madre. Siendo bebé, habló desde la cuna.",
  "Para los musulmanes, Isa es un gran profeta y mensajero de Allah, el Mesías, a quien fue revelado el Inyil (Evangelio)."],
 retenir:"Maryam, elegida entre las mujeres. Isa, nacido sin padre, profeta y Mesías.",
 sources:['q:3:42','q:3:59','q:19:30'],
 quiz:[
  {q:"¿Cuál es la única mujer nombrada en el Corán?",c:["Maryam","Jadiya","Asiya","Hawwa"],b:0,e:"Maryam es la única mujer citada por su nombre; la sura 19 lleva su nombre.",s:['f:maryam']},
  {q:"¿Qué dice el Corán de Maryam?",c:["Que Allah la eligió por encima de las mujeres de los mundos","Que era reina de Egipto","Que era profetisa de Medina","El Corán no habla de ella"],b:0,e:"Los ángeles le anunciaron que Allah la había elegido y purificado.",s:['q:3:42']},
  {q:"¿Cómo nació el profeta Isa (Jesús)?",c:["Sin padre, por voluntad de Allah","Como todo el mundo","En el palacio del Faraón","En La Meca"],b:0,e:"Allah dice «Sé», y fue.",s:['q:3:59']},
  {q:"¿Con la creación de quién compara el Corán la de Isa?",c:["Con la de Adán","Con la de los ángeles","Con la de Nuh","Con la de Iblis"],b:0,e:"Adán fue creado sin padre ni madre; Isa, sin padre.",s:['q:3:59']},
  {q:"¿Qué milagro hizo Isa cuando era bebé?",c:["Habló desde la cuna","Caminó sobre el agua","Hizo brotar el agua de Zamzam","Cruzó el mar"],b:0,e:"Defendió a su madre hablando desde la cuna.",s:['q:19:30']},
  {q:"¿Cuáles fueron las primeras palabras de Isa siendo bebé, según el Corán?",c:["«Soy el siervo de Allah»","«Soy rey»","«Soy un ángel»","«Soy el hijo de Zakariyya»"],b:0,e:"«Soy el siervo de Allah. Él me ha dado el Libro y me ha hecho profeta.»",s:['q:19:30']},
  {q:"¿Qué título da el Corán a Isa?",c:["Al-Masih, el Mesías","El Jalil","El sello de los profetas","Kalim Allah"],b:0,e:"Los ángeles anuncian a Maryam: «su nombre será el Mesías, Isa, hijo de María».",s:['q:3:45']},
  {q:"¿Qué libro reveló Allah al profeta Isa?",c:["El Inyil (Evangelio)","La Tawrat (Torá)","El Zabur (Salmos)","El Corán"],b:0,e:"«Le dimos el Evangelio, en el que hay guía y luz.»",s:['q:5:46']},
  {q:"Para los musulmanes, ¿quién es Isa?",c:["Un profeta y mensajero de Allah","Una divinidad","Un ángel","Un rey de Jerusalén"],b:0,e:"Él mismo se presenta como siervo de Allah y profeta.",s:['q:19:30']},
  {q:"¿Quién fue enviado a Maryam para anunciarle el nacimiento de Isa?",c:["El Espíritu de Allah, el ángel Yibril","Zakariyya","Yahya","El ángel Mikail"],b:0,e:"Los sabios explican que «Nuestro Espíritu» designa al ángel Yibril.",s:['q:19:19']}
 ]},
'pr-muhammad':{titre:"Muhammad ﷺ, el último profeta",
 texte:["Muhammad ﷺ nació en La Meca hacia el 570, el «año del Elefante», en la tribu de Quraysh. Huérfano de padre antes de nacer, perdió a su madre Amina a los 6 años y fue criado por su abuelo y luego por su tío Abu Talib.",
  "Conocido por su honradez, lo llamaban al-Amin, «el digno de confianza». Recibió la primera revelación a los 40 años.",
  "Murió en Medina en el 632, a la edad de 63 años. Allah lo envió como misericordia para los mundos."],
 retenir:"Nacido en La Meca hacia el 570, revelación a los 40 años, muerto en Medina a los 63.",
 sources:['q:21:107','q:68:4','h:vie'],
 quiz:[
  {q:"¿En qué ciudad nació el Profeta Muhammad ﷺ?",c:["La Meca","Medina","Jerusalén","Taif"],b:0,e:"Nació en La Meca hacia el 570.",s:['f:sira']},
  {q:"¿Cómo se llama el año de nacimiento del Profeta ﷺ?",c:["El año del Elefante","El año de la Hégira","El año de la tristeza","El año de la victoria"],b:0,e:"El año en que un ejército llegado con elefantes atacó La Meca (sura 105).",s:['q:105:1']},
  {q:"¿Cómo se llamaba la madre del Profeta ﷺ?",c:["Amina","Jadiya","Halima","Fátima"],b:0,e:"Amina bint Wahb murió cuando él tenía 6 años.",s:['f:sira']},
  {q:"¿Qué tío crió y protegió al Profeta ﷺ?",c:["Abu Talib","Abu Lahab","Hamza","Al-Abbás"],b:0,e:"Tras la muerte de su abuelo, su tío Abu Talib se hizo cargo de él.",s:['f:sira']},
  {q:"¿Qué apodo daban los mequíes al Profeta ﷺ antes de la revelación?",c:["Al-Amin, el digno de confianza","Al-Faruq","As-Siddiq","Sayf Allah"],b:0,e:"Todos lo conocían por su honradez.",s:['f:sira']},
  {q:"¿A qué edad murió el Profeta ﷺ?",c:["63 años","40 años","70 años","53 años"],b:0,e:"Ibn Abbás relata que murió a los 63 años.",s:['h:vie']},
  {q:"¿En qué ciudad murió el Profeta ﷺ?",c:["Medina","La Meca","Jerusalén","Damasco"],b:0,e:"Murió en Medina en el 632 y allí está enterrado.",s:['f:sira']},
  {q:"Según el Corán, ¿por qué envió Allah a Muhammad ﷺ?",c:["Como misericordia para los mundos","Para ser rey","Para castigar a la gente","Solo para los árabes"],b:0,e:"«No te hemos enviado sino como misericordia para los mundos.»",s:['q:21:107']},
  {q:"¿Qué dice el Corán del carácter del Profeta ﷺ?",c:["Que es de una moralidad eminente","Que es severo","Que es indiferente","El Corán no habla de ello"],b:0,e:"«Y ciertamente tienes un carácter eminente.»",s:['q:68:4']},
  {q:"¿A qué tribu pertenecía el Profeta ﷺ?",c:["Quraysh","Aws","Jazray","Zaqif"],b:0,e:"Quraysh, la gran tribu de La Meca.",s:['f:sira']}
 ]},
'pr-livres':{titre:"Los libros revelados y la fe",
 texte:["Allah reveló libros a algunos profetas: la Tawrat (Torá) a Musa, el Zabur (Salmos) a Daud, el Inyil (Evangelio) a Isa, y el Corán a Muhammad ﷺ.",
  "El Corán nombra a 25 profetas, pero Allah envió muchos más. El creyente cree en todos, sin distinción.",
  "La fe (iman) se basa en seis pilares: creer en Allah, en Sus ángeles, en Sus libros, en Sus mensajeros, en el Último Día y en el destino."],
 retenir:"Tawrat, Zabur, Inyil, Corán. Seis pilares de la fe.",
 sources:['q:5:44','q:2:285','h:jibril'],
 quiz:[
  {q:"¿Qué libro reveló Allah al profeta Musa (Moisés)?",c:["La Tawrat (Torá)","El Zabur (Salmos)","El Inyil (Evangelio)","El Corán"],b:0,e:"La Tawrat a Musa, el Zabur a Daud, el Inyil a Isa, el Corán a Muhammad ﷺ.",s:['q:5:44']},
  {q:"¿Cuántos profetas se citan por su nombre en el Corán?",c:["25","12","40","313"],b:0,e:"Se nombran 25 profetas; 18 de ellos se citan juntos en la sura Al-Anam.",s:['f:prophetes25']},
  {q:"¿Qué profeta llama el Corán «el sello de los profetas», es decir, el último?",c:["Muhammad ﷺ","Isa (Jesús)","Musa (Moisés)","Ibrahim (Abraham)"],b:0,e:"Muhammad ﷺ es el último de los profetas.",s:['q:33:40']},
  {q:"¿Qué libro fue revelado al profeta Daud (David)?",c:["El Zabur (Salmos)","La Tawrat","El Inyil","Las hojas de Ibrahim"],b:0,e:"«Y dimos a Daud el Zabur.»",s:['q:4:163']},
  {q:"¿Forma parte de la fe del musulmán creer en los libros revelados?",c:["Sí, es un pilar de la fe","No, solo en el Corán","No, es opcional","Solo durante Ramadán"],b:0,e:"Los creyentes creen en Allah, en Sus ángeles, en Sus libros y en Sus mensajeros.",s:['q:2:285']},
  {q:"¿Cuántos pilares tiene la fe (iman)?",c:["6","5","4","10"],b:0,e:"Allah, los ángeles, los libros, los mensajeros, el Último Día y el destino.",s:['h:jibril']},
  {q:"¿Cuál de estos elementos NO es un pilar de la fe (iman)?",c:["El ayuno de Ramadán","La creencia en los ángeles","La creencia en el Último Día","La creencia en los libros"],b:0,e:"El ayuno es un pilar del islam (la práctica), no de la fe (la creencia).",s:['h:jibril']},
  {q:"¿Qué libro se comprometió Allah a preservar?",c:["El Corán","La Tawrat","El Zabur","Todos los libros de los reyes"],b:0,e:"«Somos Nosotros sus guardianes.»",s:['q:15:9']},
  {q:"¿Cuenta el Corán la historia de todos los mensajeros enviados por Allah?",c:["No, solo la de algunos","Sí, la de todos","No cuenta ninguna","Solo la de los árabes"],b:0,e:"«Hay mensajeros cuya historia te hemos contado y otros cuya historia no te hemos contado.»",s:['q:4:164']},
  {q:"Según el Corán, ¿hacen los creyentes distinción entre los mensajeros en su fe?",c:["No, creen en todos","Sí, solo creen en uno","Sí, rechazan a los antiguos","No creen en ninguno"],b:0,e:"«No hacemos distinción entre ninguno de Sus mensajeros.»",s:['q:2:285']}
 ]},

/* ===================== HISTORIA Y COMPAÑEROS ===================== */
'h-khadija':{titre:"Jadiya y los comienzos del islam",
 texte:["Jadiya era una comerciante respetada de La Meca. Se casó con el Profeta ﷺ, que tenía entonces 25 años.",
  "Tras la primera revelación, fue ella quien lo reconfortó y la primera en creer en él. Lo llevó a ver a su primo Waraqa ibn Nawfal.",
  "Entre los primeros musulmanes figuran Abu Bakr, Ali, Zayd ibn Hariza y Bilal. Durante 13 años, en La Meca, los musulmanes fueron perseguidos; Sumayya fue la primera mártir."],
 retenir:"Jadiya, la primera en creer. 13 años de predicación en La Meca.",
 sources:['h:hira','f:debuts'],
 quiz:[
  {q:"¿Quién fue la primera esposa del Profeta ﷺ?",c:["Jadiya","Aisha","Hafsa","Zaynab"],b:0,e:"Jadiya fue la primera persona en creer en su mensaje.",s:['h:hira']},
  {q:"¿Quién reconfortó al Profeta ﷺ justo después de la primera revelación en la cueva de Hira?",c:["Jadiya","Abu Bakr","Ali","Bilal"],b:0,e:"Volvió junto a Jadiya, que lo tranquilizó.",s:['h:hira']},
  {q:"¿A qué actividad se dedicaba Jadiya en La Meca?",c:["Al comercio","A la medicina","A la poesía","A la cría de camellos"],b:0,e:"Era una rica comerciante respetada.",s:['f:debuts']},
  {q:"¿Qué edad tenía el Profeta ﷺ cuando se casó con Jadiya?",c:["25 años","40 años","18 años","30 años"],b:0,e:"Tenía 25 años.",s:['f:debuts']},
  {q:"¿A casa de quién llevó Jadiya al Profeta ﷺ después de la primera revelación?",c:["De su primo Waraqa ibn Nawfal","De Abu Talib","De Abu Bakr","Del rey de Abisinia"],b:0,e:"Waraqa conocía las Escrituras antiguas.",s:['h:hira']},
  {q:"¿Qué muchacho joven estuvo entre los primeros en abrazar el islam?",c:["Ali ibn Abi Talib","Umar","Jalid","Muawiya"],b:0,e:"Ali, primo del Profeta ﷺ, era todavía un niño.",s:['f:debuts']},
  {q:"¿Durante cuántos años aproximadamente predicó el Profeta ﷺ en La Meca antes de la Hégira?",c:["13 años","3 años","23 años","40 años"],b:0,e:"Ibn Abbás relata que permaneció 13 años en La Meca después de la revelación.",s:['h:vie']},
  {q:"¿Qué amigo del Profeta ﷺ fue el primer hombre adulto en abrazar el islam?",c:["Abu Bakr","Umar","Uzmán","Hamza"],b:0,e:"Abu Bakr creyó en él sin dudar.",s:['f:debuts']},
  {q:"¿Qué antiguo esclavo, perseguido por su fe, se convirtió en el primer muecín del islam?",c:["Bilal ibn Rabah","Zayd ibn Hariza","Salmán","Anas"],b:0,e:"Su voz llegaba lejos: el Profeta ﷺ le confió el adhan.",s:['h:adhan']},
  {q:"¿Cómo se llamaba la primera mártir del islam?",c:["Sumayya","Jadiya","Fátima","Asma"],b:0,e:"Sumayya, madre de Ammar, fue asesinada por su fe en La Meca.",s:['f:debuts']}
 ]},
'h-hegire':{titre:"La Hégira",
 texte:["En el 622, ante las persecuciones, el Profeta ﷺ dejó La Meca por Medina, llamada entonces Yazrib: es la Hégira. Marca el año 1 del calendario musulmán.",
  "Durante el viaje, se escondió en la cueva de Zawr con su amigo Abu Bakr.",
  "En Medina lo acogieron los Ansar (los «Auxiliares»), que compartieron sus bienes con los Muhayirun (los «Emigrantes»). Allí construyó su mezquita."],
 retenir:"622: la Hégira, año 1. Muhayirun y Ansar.",
 sources:['q:9:40','f:hegire'],
 quiz:[
  {q:"¿Qué es la Hégira?",c:["La emigración del Profeta ﷺ de La Meca a Medina","La primera peregrinación","Una batalla","El nacimiento del Profeta ﷺ"],b:0,e:"Marca el año 1 del calendario musulmán.",s:['f:hegire']},
  {q:"¿Qué compañero acompañaba al Profeta ﷺ en la cueva durante la Hégira?",c:["Abu Bakr as-Siddiq","Umar ibn al-Jattab","Ali ibn Abi Talib","Bilal"],b:0,e:"Abu Bakr era «el segundo de los dos» en la cueva.",s:['q:9:40']},
  {q:"¿En qué año tuvo lugar la Hégira?",c:["622","570","632","610"],b:0,e:"La Hégira tuvo lugar en el año 622 de la era cristiana.",s:['f:hegire']},
  {q:"¿En qué cueva se escondió el Profeta ﷺ durante la Hégira?",c:["La cueva de Zawr","La cueva de Hira","La cueva de Uhud","La cueva de Badr"],b:0,e:"Zawr está al sur de La Meca; Hira, lugar de la primera revelación, al norte.",s:['f:hegire']},
  {q:"¿Cuál era el antiguo nombre de Medina?",c:["Yazrib","Bakka","Taif","Quba"],b:0,e:"El Corán cita este nombre: «¡Oh gente de Yazrib!».",s:['q:33:13']},
  {q:"¿Cómo se llama a los habitantes de Medina que acogieron a los musulmanes?",c:["Los Ansar","Los Muhayirun","Los Quraysh","Los Banu Israil"],b:0,e:"Ansar significa «los Auxiliares».",s:['q:9:100']},
  {q:"¿Cómo se llama a los musulmanes que emigraron de La Meca a Medina?",c:["Los Muhayirun","Los Ansar","Los jariyíes","Los beduinos"],b:0,e:"Muhayirun significa «los Emigrantes».",s:['q:9:100']},
  {q:"Según el Corán, ¿qué le dijo el Profeta ﷺ a Abu Bakr en la cueva?",c:["«No te entristezcas, Allah está con nosotros»","«Huyamos rápido»","«Volvamos a La Meca»","«Combatámoslos»"],b:0,e:"Es la aleya 40 de la sura At-Tawba.",s:['q:9:40']},
  {q:"¿Bajo qué califa se adoptó el calendario de la Hégira?",c:["Umar","Abu Bakr","Uzmán","Ali"],b:0,e:"Umar hizo de la Hégira el punto de partida del calendario.",s:['f:hegire']},
  {q:"¿Qué construyó el Profeta ﷺ al llegar a Medina?",c:["Su mezquita","Un palacio","Una fortaleza","Un mercado"],b:0,e:"La Mezquita del Profeta (al-Masyid an-Nabawi).",s:['f:hegire']}
 ]},
'h-badr':{titre:"La batalla de Badr",
 texte:["El 17 de Ramadán del año 2 de la Hégira (624), los musulmanes se enfrentaron al ejército de Quraysh cerca de los pozos de Badr.",
  "Eran unos 313, frente a cerca de 1000 combatientes. Allah los apoyó con ángeles y obtuvieron la victoria.",
  "El Corán llama a este día «el día del Discernimiento» (yawm al-furqan), aquel en que la verdad se distinguió del error."],
 retenir:"17 de Ramadán del año 2: Badr, 313 contra 1000, el día del Discernimiento.",
 sources:['q:3:123','q:8:9','q:8:41'],
 quiz:[
  {q:"¿Durante qué mes tuvo lugar la batalla de Badr?",c:["Ramadán","Muharram","Dhul-Hiyya","Rajab"],b:0,e:"El 17 de Ramadán del año 2 de la Hégira.",s:['f:badr']},
  {q:"¿En qué año de la Hégira tuvo lugar la batalla de Badr?",c:["El año 2","El año 8","El año 10","El año 1"],b:0,e:"En el 624 de la era cristiana.",s:['f:badr']},
  {q:"¿Cuántos musulmanes aproximadamente combatieron en Badr?",c:["Unos 313","Unos 3000","Unos 10 000","Unos 50"],b:0,e:"Eran unos 313.",s:['f:badr']},
  {q:"¿Cuántos combatientes aproximadamente tenía el ejército de Quraysh en Badr?",c:["Cerca de 1000","Cerca de 100","Cerca de 10 000","Cerca de 300"],b:0,e:"Los mequíes eran tres veces más numerosos.",s:['f:badr']},
  {q:"Según el Corán, ¿cómo apoyó Allah a los musulmanes en Badr?",c:["Con ángeles","Con una tormenta de arena","Con refuerzos de Persia","Solo con la lluvia"],b:0,e:"Allah respondió a su llamada enviando ángeles.",s:['q:8:9']},
  {q:"Según la sura Al-Anfal, ¿cuántos ángeles prometió Allah enviar como refuerzo en Badr?",c:["Mil","Cien","Diez","Trescientos"],b:0,e:"«Os ayudaré con mil ángeles que llegarán uno tras otro.»",s:['q:8:9']},
  {q:"¿Cómo llama el Corán al día de Badr?",c:["El día del Discernimiento (yawm al-furqan)","El día de la Resurrección","El día del Eid","El día de la Hégira"],b:0,e:"El día en que la verdad se distinguió del error.",s:['q:8:41']},
  {q:"¿Contra qué tribu combatieron los musulmanes en Badr?",c:["Quraysh","Los romanos","Los persas","Los Ansar"],b:0,e:"El ejército de Quraysh venía de La Meca.",s:['f:badr']},
  {q:"¿Qué día de Ramadán tuvo lugar la batalla de Badr?",c:["El 17","El 27","El 1","El 10"],b:0,e:"El 17 de Ramadán del año 2.",s:['f:badr']},
  {q:"Según el Corán, ¿en qué situación estaban los musulmanes en Badr?",c:["Eran débiles y humillados","Eran muy numerosos","Eran ricos","Iban a caballo"],b:0,e:"«Allah os dio la victoria en Badr cuando erais humillados.»",s:['q:3:123']}
 ]},
'h-fath':{titre:"La conquista de La Meca",
 texte:["En el año 8 de la Hégira (630), durante el mes de Ramadán, el Profeta ﷺ entró en La Meca con unos 10 000 musulmanes, casi sin combate.",
  "Perdonó a sus antiguos enemigos y purificó la Kaaba de sus 360 ídolos, recitando: «Ha llegado la verdad y ha desaparecido la falsedad.»",
  "La sura An-Nasr anuncia este auxilio de Allah y la entrada de la gente en masa en el islam."],
 retenir:"Ramadán del año 8: La Meca abierta, los ídolos destruidos, el perdón concedido.",
 sources:['q:17:81','h:idoles','q:110:1'],
 quiz:[
  {q:"¿En qué año de la Hégira fue conquistada La Meca?",c:["El año 8","El año 2","El año 1","El año 11"],b:0,e:"En el 630 de la era cristiana.",s:['f:fath']},
  {q:"¿Durante qué mes tuvo lugar la conquista de La Meca?",c:["Ramadán","Shawwal","Dhul-Hiyya","Muharram"],b:0,e:"La conquista de La Meca tuvo lugar en Ramadán.",s:['f:fath']},
  {q:"¿Cuántos musulmanes aproximadamente acompañaban al Profeta ﷺ en la conquista de La Meca?",c:["Unos 10 000","Unos 313","Unos 1000","Unos 100"],b:0,e:"Un ejército de unos 10 000 hombres.",s:['f:fath']},
  {q:"¿Cuántos ídolos rodeaban la Kaaba el día de la conquista de La Meca?",c:["360","12","99","1000"],b:0,e:"Abdallah ibn Masud relata que había 360.",s:['h:idoles']},
  {q:"¿Qué aleya recitó el Profeta ﷺ al derribar los ídolos de la Kaaba?",c:["«Ha llegado la verdad y ha desaparecido la falsedad»","«En el nombre de Allah»","«Di: Él es Allah, Uno»","«¡Lee!»"],b:0,e:"Es la aleya 81 de la sura Al-Isra.",s:['q:17:81','h:idoles']},
  {q:"¿Cómo trató el Profeta ﷺ a sus antiguos enemigos mequíes después de la conquista?",c:["Los perdonó","Los expulsó","Los encarceló","Los desterró a Abisinia"],b:0,e:"Concedió un perdón general a los mequíes.",s:['f:fath']},
  {q:"¿Qué sura anuncia «el auxilio de Allah y la victoria»?",c:["An-Nasr (110)","Al-Fath (48)","Al-Fil (105)","Al-Kawzar (108)"],b:0,e:"«Cuando llegue el auxilio de Allah y la victoria.»",s:['q:110:1']},
  {q:"Según la sura An-Nasr, ¿cómo entró la gente en el islam?",c:["En masa","Uno a uno, en secreto","Por la fuerza","No entró nadie"],b:0,e:"«Y veas a la gente entrar en masa en la religión de Allah.»",s:['q:110:2']},
  {q:"¿Se hizo la conquista de La Meca mediante una gran batalla?",c:["No, casi sin combate","Sí, la mayor de la historia","Sí, durante un año","Sí, al pie del monte Uhud"],b:0,e:"La ciudad se abrió pacíficamente, casi sin enfrentamiento.",s:['f:fath']},
  {q:"¿Qué pide la sura An-Nasr después de la victoria?",c:["Glorificar a Allah y pedirle perdón","Hacer el hajj enseguida","Ayunar tres días","Reconstruir la Kaaba"],b:0,e:"«Glorifica con alabanzas a tu Señor y pídele perdón.»",s:['q:110:3']}
 ]},
'h-califes':{titre:"Los cuatro primeros califas",
 texte:["Tras la muerte del Profeta ﷺ en el 632, se sucedieron cuatro califas: Abu Bakr, Umar, Uzmán y Ali. Se les llama los «califas bien guiados».",
  "Abu Bakr hizo reunir el Corán en una sola recopilación a cargo de Zayd ibn Zabit. Bajo Umar, el islam se extendió y se adoptó el calendario de la Hégira.",
  "Uzmán hizo copiar el Corán en varios ejemplares enviados a las provincias. Ali, primo y yerno del Profeta ﷺ, fue el cuarto califa."],
 retenir:"Abu Bakr, Umar, Uzmán, Ali: los cuatro califas bien guiados.",
 sources:['h:compilation','h:copies','f:califes'],
 quiz:[
  {q:"¿Quién fue el primer califa tras la muerte del Profeta ﷺ?",c:["Abu Bakr","Umar","Ali","Uzmán"],b:0,e:"Abu Bakr, luego Umar, Uzmán y Ali.",s:['f:califes']},
  {q:"¿Cuántos «califas bien guiados» sucedieron al Profeta ﷺ?",c:["4","3","5","12"],b:0,e:"Se les llama al-julafa ar-rashidun.",s:['f:califes']},
  {q:"¿Cuál es el orden de los cuatro primeros califas?",c:["Abu Bakr, Umar, Uzmán, Ali","Ali, Umar, Abu Bakr, Uzmán","Umar, Abu Bakr, Ali, Uzmán","Uzmán, Ali, Umar, Abu Bakr"],b:0,e:"Del 632 al 661.",s:['f:califes']},
  {q:"¿Bajo qué califa se reunió el Corán por primera vez en una sola recopilación?",c:["Abu Bakr","Umar","Uzmán","Ali"],b:0,e:"Después de la batalla de Yamama, en la que murieron muchos recitadores.",s:['h:compilation']},
  {q:"¿Qué compañero fue encargado de reunir el Corán bajo Abu Bakr?",c:["Zayd ibn Zabit","Bilal","Jalid ibn al-Walid","Salmán"],b:0,e:"Zayd ibn Zabit había sido escriba de la revelación.",s:['h:compilation']},
  {q:"¿Qué califa hizo copiar el Corán en varios ejemplares enviados a las provincias?",c:["Uzmán","Abu Bakr","Umar","Ali"],b:0,e:"Para unificar la recitación en todo el mundo musulmán.",s:['h:copies']},
  {q:"¿Qué parentesco unía a Ali con el Profeta ﷺ?",c:["Era su primo y yerno","Era su hermano","Era su tío","Era su abuelo"],b:0,e:"Ali era el esposo de Fátima, hija del Profeta ﷺ.",s:['f:califes']},
  {q:"¿Qué califa era apodado «al-Faruq», el que distingue lo verdadero de lo falso?",c:["Umar","Abu Bakr","Uzmán","Ali"],b:0,e:"Umar ibn al-Jattab.",s:['f:califes']},
  {q:"¿Qué califa era apodado «as-Siddiq», el veraz?",c:["Abu Bakr","Umar","Uzmán","Ali"],b:0,e:"Abu Bakr creyó de inmediato todo lo que relataba el Profeta ﷺ.",s:['f:califes']},
  {q:"¿Qué califa se casó sucesivamente con dos hijas del Profeta ﷺ?",c:["Uzmán","Umar","Abu Bakr","Ali"],b:0,e:"De ahí su apodo «Dhu n-Nurayn», el de las dos luces.",s:['f:califes']}
 ]}
},

/* Referencias (fuentes históricas o prácticas, sin texto árabe) */
faits:{
 mois:{titre:"Referencia",texte:"Los 12 meses de la Hégira: Muharram, Safar, Rabi al-awwal, Rabi az-zani, Yumada al-ula, Yumada al-ajira, Rajab, Shaabán, Ramadán, Shawwal, Dhul-Qada, Dhul-Hiyya."},
 jeune2:{titre:"Referencia histórica",texte:"El ayuno de Ramadán fue prescrito en Medina, en el año 2 de la Hégira (624)."},
 conditions:{titre:"Referencia",texte:"Los sabios establecen como condiciones de la obligación del ayuno: ser musulmán, púber, estar en su sano juicio y ser capaz de ayunar."},
 aid:{titre:"Referencia",texte:"El islam tiene dos fiestas: el Eid al-Fitr, el 1 de Shawwal, al final de Ramadán, y el Eid al-Adha, el 10 de Dhul-Hiyya, durante el hajj."},
 shahada:{titre:"Referencia",texte:"Texto de la shahada: «Ash-hadu an lâ ilâha illâ Llâh, wa ash-hadu anna Muḥammadan rasûlu Llâh» — «Atestiguo que no hay más divinidad que Allah, y atestiguo que Muhammad es el Mensajero de Allah»."},
 rakat:{titre:"Práctica transmitida",texte:"El número de unidades de cada oración procede de la práctica del Profeta ﷺ, transmitida por todos los musulmanes: Fajr 2, Dhuhr 4, Asr 4, Maghrib 3, Isha 4, es decir, 17 rakat al día."},
 zakat:{titre:"Referencia",texte:"El zakat del dinero es del 2,5 % (una cuarentava parte) de los ahorros que alcanzan el nisab y permanecen en posesión durante un año lunar (el hawl). La sadaqa es una limosna voluntaria. Para los casos particulares, hay que preguntar a un sabio."},
 hajj:{titre:"Referencia",texte:"El hajj tiene lugar del 8 al 13 de Dhul-Hiyya. El peregrino entra en ihram (los hombres llevan dos piezas de tela blanca sin costuras), hace el tawaf (siete vueltas a la Kaaba) y el sai (siete recorridos entre Safa y Marwa). El 9 es el día de Arafa, el 10 el Eid al-Adha."},
 coran:{titre:"Referencia",texte:"El Corán tiene 114 suras y 6236 aleyas según el cómputo más extendido. Está dividido en 30 partes (yuz). Un versículo se dice aya (aleya). Las suras reveladas antes de la Hégira se llaman mequíes, y las posteriores, medinenses. La más larga es Al-Baqara (286 aleyas)."},
 tawba:{titre:"Referencia",texte:"La sura At-Tawba (9) es la única de las 114 suras que no comienza con «Bismi Llâhi r-Raḥmâni r-Raḥîm»."},
 ikhlas:{titre:"Referencia",texte:"Al-Ijlas significa «el monoteísmo puro, la sinceridad»: la sura purifica la fe de toda asociación."},
 hawwa:{titre:"Referencia",texte:"El Corán menciona a la esposa de Adán sin nombrarla. Su nombre, Hawwa (Eva), procede de la Sunna y de los sabios."},
 musa:{titre:"Referencia",texte:"Musa es el profeta más nombrado en el Corán: más de 130 veces."},
 maryam:{titre:"Referencia",texte:"Maryam es la única mujer citada por su nombre en el Corán. La sura 19 lleva su nombre."},
 sira:{titre:"Referencia histórica",texte:"El Profeta ﷺ nació en La Meca hacia el 570, en la tribu de Quraysh. Huérfano de padre, perdió a su madre Amina a los 6 años y fue criado por su abuelo Abd al-Muttalib y luego por su tío Abu Talib. Lo llamaban al-Amin. Murió en Medina en el 632."},
 prophetes25:{titre:"Referencia",texte:"En el Corán se nombran 25 profetas. 18 de ellos se citan juntos en la sura Al-Anam (6), aleyas 83 a 86."},
 debuts:{titre:"Referencia histórica",texte:"Jadiya, rica comerciante, se casó con el Profeta ﷺ cuando él tenía 25 años. Entre los primerísimos musulmanes: Jadiya, Abu Bakr, Ali (todavía niño) y Zayd ibn Hariza. Bilal, esclavo perseguido y luego liberado, se convirtió en el primer muecín. Sumayya, madre de Ammar, fue la primera mártir."},
 hegire:{titre:"Referencia histórica",texte:"La Hégira tuvo lugar en el 622. El Profeta ﷺ y Abu Bakr se escondieron en la cueva de Zawr. Medina se llamaba Yazrib. El Profeta ﷺ construyó allí su mezquita. El calendario de la Hégira se adoptó durante el califato de Umar."},
 badr:{titre:"Referencia histórica",texte:"La batalla de Badr tuvo lugar el 17 de Ramadán del año 2 (624). Unos 313 musulmanes hicieron frente a cerca de 1000 combatientes de Quraysh."},
 fath:{titre:"Referencia histórica",texte:"La Meca fue abierta en Ramadán del año 8 (630), casi sin combate, por unos 10 000 musulmanes. El Profeta ﷺ concedió un perdón general a los mequíes."},
 califes:{titre:"Referencia histórica",texte:"Los cuatro califas bien guiados: Abu Bakr as-Siddiq (632-634), Umar al-Faruq (634-644), Uzmán Dhu n-Nurayn (644-656), que se casó con dos hijas del Profeta ﷺ, Ruqayya y luego Umm Kulzum, y Ali (656-661), primo del Profeta ﷺ y esposo de su hija Fátima."}
},

/* Resúmenes mostrados para los hadices largos (el texto completo sigue disponible) */
resumes:{
 cinq:"Durante el Viaje nocturno (al-Isra wal-Miray) se prescribieron primero cincuenta oraciones, que luego se aligeraron hasta cinco oraciones al día.",
 enfants:"Ar-Rubayyi bint Muawwidh cuenta que los compañeros hacían ayunar a sus hijos pequeños el día de Ashura y les daban juguetes de lana para que aguantaran hasta la ruptura del ayuno.",
 hira:"Aisha cuenta que el Profeta ﷺ se retiraba a la cueva de Hira. El ángel vino y le dijo: «¡Lee!». Volvió junto a Jadiya, que lo reconfortó y luego lo llevó a ver a su primo Waraqa ibn Nawfal.",
 regles:"Aisha explica que se les ordenaba recuperar el ayuno perdido durante la menstruación, pero no la oración.",
 tarawih:"El Profeta ﷺ rezó de noche en la mezquita durante Ramadán; la gente rezó detrás de él, cada vez en mayor número. Luego dejó de salir, por temor a que esta oración se les hiciera obligatoria.",
 adhan:"El compañero Abdallah ibn Zayd vio en sueños las palabras del adhan. El Profeta ﷺ confirmó ese sueño y pidió a Bilal que hiciera la llamada, porque su voz llegaba más lejos.",
 ikhlas:"Un hombre recitaba sin cesar la sura Al-Ijlas y le parecía poca cosa. El Profeta ﷺ dijo: «Equivale a un tercio del Corán.»",
 kursi:"El Profeta ﷺ preguntó a Ubayy ibn Kab cuál es la aleya más grande del Libro de Allah. Respondió: Ayat al-Kursi. El Profeta ﷺ lo felicitó por su conocimiento.",
 hajj_une:"El Profeta ﷺ anunció que el hajj había sido prescrito. Un hombre preguntó: «¿Cada año?». Respondió que, si decía que sí, se volvería obligatorio cada año: es obligatorio una vez.",
 arafa:"Unas personas preguntaron al Profeta ﷺ en Arafa sobre la peregrinación. Respondió: «El hajj es Arafa.»",
 jibril:"El ángel Yibril, en forma humana, preguntó al Profeta ﷺ sobre el islam, la fe y la excelencia. La fe (iman): creer en Allah, en Sus ángeles, en Sus libros, en Sus mensajeros, en el Último Día y en el destino, bueno o malo.",
 vie:"Ibn Abbás relata que el Profeta ﷺ recibió la revelación a los 40 años, permaneció 13 años en La Meca, emigró a Medina, donde vivió 10 años, y murió a los 63.",
 idoles:"El día de la conquista había 360 ídolos alrededor de la Kaaba. El Profeta ﷺ los golpeaba con un bastón recitando: «Ha llegado la verdad y ha desaparecido la falsedad.»",
 compilation:"Después de la batalla de Yamama, en la que murieron muchos recitadores, Abu Bakr encargó a Zayd ibn Zabit reunir el Corán en una sola recopilación.",
 copies:"Uzmán, preocupado por las diferencias de recitación entre las provincias, hizo copiar la recopilación del Corán en varios ejemplares enviados a cada región.",
 fitr_but:"Ibn Abbás relata que el Profeta ﷺ prescribió el zakat al-fitr para purificar a quien ayuna de las palabras vanas e indecentes, y para alimentar a los pobres.",
 afw:"Aisha preguntó qué decir si sabía cuál era la Noche del Decreto. Él respondió: «Di: Allâhumma innaka ʿafuwwun tuḥibbu l-ʿafwa faʿfu ʿannî» — Oh Allah, Tú eres el que perdona, amas el perdón, así que perdóname."
}
};
